/* Original reading library. No copied novel. Extensive mode has no dictionary. */
(function (root) {
  function text(id, level, title, body) {
    return { id: id, level: level, title: title, body: body, words: body.split(/\s+/).filter(Boolean).length };
  }
  const A1 = [
    ['a1-r1', 'بطاقة الفندق', 'Guten Tag. Ich heiße Sara. Ich wohne in Berlin und arbeite in einem Hotel. Das Hotel ist klein, aber hell. Ich habe ein Zimmer im ersten Stock. Das Zimmer ist ruhig, es hat ein Bett, einen Tisch und zwei Stühle. Am Morgen trinke ich Kaffee, dann gehe ich zur Arbeit. Am Abend lese ich ein Buch oder ich höre Musik. Ich bleibe zwei Nächte in der Stadt, dann fahre ich nach Hause.'],
    ['a1-r2', 'قائمة قصيرة', 'Im Café am Markt gibt es Kaffee, Tee und Kuchen. Ein Kaffee kostet zwei Euro, ein Stück Kuchen drei Euro. Ich bestelle einen Kaffee und ein Wasser. Die Frau bringt die Getränke schnell. Mein Freund isst einen Salat, er trinkt keinen Kaffee, er möchte Tee mit Milch. Wir sprechen über die Arbeit und über die Familie. Am Ende bezahlen wir zusammen und geben drei Euro mehr. Die Rechnung liegt auf dem Tisch.'],
    ['a1-r3', 'رسالة إلى صديق', 'Liebe Anna, wie geht es dir? Ich habe eine neue Wohnung. Sie ist im dritten Stock und hat zwei Zimmer. Die Küche ist klein, aber die Fenster sind groß. Am Montag kaufe ich einen Tisch und einen Schrank, am Dienstag kommt mein Bruder und hilft mir. Am Samstag mache ich eine Party. Kommst du um sieben? Bring bitte Musik mit. Ich freue mich sehr. Viele Grüße, Sara.'],
    ['a1-r4', 'إعلان غرفة', 'Zimmer frei ab Montag. Das Zimmer ist hell und ruhig, es liegt im zweiten Stock. Es gibt ein Bett, einen Tisch, einen Stuhl und ein Regal. Die Küche und das Bad teilen wir zu dritt. Die Wohnung ist in der Stadt, die Haltestelle ist fünf Minuten zu Fuß. Preis: 300 Euro im Monat, alles zusammen. Keine Tiere. Fragen? Rufen Sie abends an.'],
    ['a1-r5', 'لافتة قطار', 'Der Zug nach Frankfurt kommt um acht Uhr auf Gleis zwei. Der Zug hat heute zehn Minuten Verspätung. Fahrkarten kaufen Sie am Automaten oder im Internet. Ein Ticket nach Frankfurt kostet vierzig Euro. Kinder bis sechs Jahre bezahlen nichts. Im Zug gibt es keinen Kaffee, aber Wasser. In Frankfurt ist der Zug um zwölf Uhr. Bitte einsteigen und die Türen schließen.'],
    ['a1-r6', 'ملاحظة', 'Hallo Ben, ich bin im Kurs und komme um sechs Uhr nach Hause. Es gibt Brot, Käse und Obst auf dem Tisch. Die Milch ist im Kühlschrank. Bitte kaufe noch zwei Flaschen Wasser, das Geld liegt in der Küche. Um sieben Uhr kommt mein Bruder, wir essen zusammen. Wenn du müde bist, schlaf eine Stunde. Bis später! Sara.'],
    ['a1-r7', 'دعوة', 'Liebe Nachbarn, am Samstag feiern wir meinen Geburtstag. Die Party beginnt um sieben Uhr im Garten. Wir essen, trinken und tanzen. Bitte bringt Musik mit, wir haben nur ein Radio. Es gibt Kuchen, Salat und Getränke. Kinder sind willkommen. Die Wohnung ist im ersten Stock, der Garten ist hinter dem Haus. Sagt bitte bis Donnerstag, ob ihr kommt. Viele Grüße, Sara und Ben.'],
    ['a1-r8', 'وصفة قصيرة', 'Heute koche ich Reis mit Gemüse. Zuerst wasche ich das Gemüse und mache es klein. Dann koche ich Wasser. Der Reis braucht zwanzig Minuten, das Gemüse nur zehn. Danach koche ich alles zusammen, ich brauche Salz und Öl. Zum Schluss esse ich mit meiner Schwester. Das Essen ist einfach und billig. Am Abend trinken wir Tee und sprechen über den Tag.'],
    ['a1-r9', 'جدول', 'Der Bus kommt um neun Uhr an der Haltestelle. Die Fahrt dauert zwanzig Minuten. Ich steige am Bahnhof um und nehme den Bus vier. Am Montag arbeite ich von acht bis zwölf, am Dienstag von zwei bis sechs. Am Mittwoch habe ich frei, dann lerne ich Deutsch. Der Kurs beginnt um fünf Uhr und dauert neunzig Minuten. Danach gehe ich zu Fuß nach Hause.'],
    ['a1-r10', 'بريد قصير', 'Liebe Frau Meier, ich bin krank und kann heute nicht in den Kurs kommen. Ich habe Fieber und mein Kopf tut weh. Der Arzt sagt: Bleiben Sie zwei Tage im Bett und trinken Sie viel Wasser. Am Donnerstag komme ich wieder. Bitte schicken Sie mir die Hausaufgabe. Vielen Dank und viele Grüße, Sara.']
  ].map(r => text(r[0], 'A1', r[1], r[2]));
  const A2 = [
    ['Der Tag in Berlin', 'Ich bin am Freitag mit dem Zug nach Berlin gefahren. Die Fahrt hat drei Stunden gedauert. Am Bahnhof habe ich eine Fahrkarte für die Stadt gekauft. Zuerst war ich in einem Museum, danach habe ich mir den Platz angesehen. Am Nachmittag habe ich in einem kleinen Restaurant gegessen. Das Essen war teuer, aber sehr gut. Am Abend habe ich meine Freundin getroffen, wir sind durch die Stadt gegangen und haben über die Arbeit gesprochen. Um zehn Uhr war ich müde. Ich habe ein Zimmer im Hotel genommen und sofort geschlafen.'],
    ['Beim Arzt', 'Ich habe seit drei Tagen Husten und mein Kopf tut weh. Am Morgen habe ich in der Praxis angerufen und einen Termin bekommen. Der Arzt hat mich untersucht und gefragt, ob ich Fieber habe. Ich habe gesagt, dass ich mich müde fühle und nicht gut schlafe. Er hat mir ein Rezept gegeben und gesagt: Nehmen Sie die Tabletten drei Mal am Tag und trinken Sie viel Wasser. Sie müssen eine Woche nicht arbeiten. Ich habe mich bedankt und bin nach Hause gegangen. Am Abend war ich schon etwas besser.'],
    ['Das Wochenende', 'Am Samstag sind wir ans Meer gefahren. Das Wetter war warm und die Sonne hat geschienen. Wir haben am Wasser gesessen und die Kinder haben im Wasser gespielt. Zum Mittag haben wir Brot, Käse und Obst gegessen. Am Nachmittag wollten wir spazieren gehen, aber es hat angefangen zu regnen. Deshalb sind wir in ein Café gegangen und haben Kaffee getrunken. Am Sonntag sind wir zu Hause geblieben. Ich habe die Wohnung geputzt und mein Mann hat das Essen gemacht. Es war ein ruhiges Wochenende, und das war gut so.'],
    ['Der erste Arbeitstag', 'Am Montag habe ich meine neue Arbeit angefangen. Ich muss um acht Uhr im Büro sein, deshalb bin ich früh aufgestanden. Meine Kollegen waren freundlich und haben mir alles gezeigt. Ich habe einen Computer bekommen und viele Papiere gelesen. Am Mittag haben wir zusammen gegessen. Die Arbeit ist nicht schwer, aber ich muss viel sprechen. Um sechzehn Uhr war ich fertig und bin nach Hause gefahren. Ich bin müde, aber ich freue mich. In der ersten Woche lerne ich die Namen und die Aufgaben. Danach kann ich allein arbeiten.'],
    ['Die neue Wohnung', 'Wir haben endlich eine neue Wohnung gefunden. Sie ist im dritten Stock und hat drei Zimmer. Die Küche ist groß und hell, aber das Schlafzimmer ist klein. Wir brauchen noch einen Tisch, einen Schrank und ein Sofa. Am Samstag haben unsere Freunde geholfen und alle Sachen getragen. Die Nachbarn sind ruhig und freundlich. Hinter dem Haus gibt es einen Garten, dort können die Kinder spielen. Die Miete ist höher als in der alten Wohnung, aber die Lage ist besser. In zwei Wochen wollen wir ein Fest machen.'],
    ['Das Fest', 'Am nächsten Samstag wird meine Schwester dreißig Jahre alt. Wir machen ein Fest im Garten. Ich habe schon die Getränke gekauft und meine Mutter backt einen Kuchen. Meine Schwester weiß nichts, wir sagen es ihr nicht. Wir haben zwanzig Leute eingeladen. Jeder bringt etwas mit: Salat, Brot oder Musik. Um sieben Uhr kommen die Gäste, und um acht Uhr kommt meine Schwester. Dann rufen wir alle zusammen. Ich hoffe, dass das Wetter gut ist und dass alle Spaß haben. Danach schreiben wir Fotos und schicken sie der Familie.'],
    ['Der Regen', 'Es regnet seit drei Tagen. Der Himmel ist grau und die Straßen sind nass. Ich wollte mit dem Fahrrad zur Arbeit fahren, aber ich habe den Bus genommen. Am Morgen war der Bus voll und ich bin zu spät gekommen. Zu Hause ist die Wäsche noch nass, weil ich sie nicht draußen trocknen kann. Am Abend haben wir Tee getrunken und einen Film gesehen. Meine Tochter hat gespielt und mein Sohn hat gelesen. Morgen soll die Sonne wieder scheinen. Dann gehen wir in den Park und machen einen langen Spaziergang.'],
    ['Die Tasche', 'Gestern habe ich meine Tasche verloren. Ich war im Zug und habe sie unter dem Sitz gelassen. In der Tasche waren mein Buch, meine Fahrkarte und mein Telefon. Ich habe sofort am Bahnhof gefragt. Die Frau am Schalter hat angerufen und gesagt, dass jemand die Tasche gefunden hat. Eine Stunde später habe ich sie abgeholt. Alles war noch da, nur das Buch war weg. Ich war so froh, dass ich der Frau Blumen gekauft habe. Seit diesem Tag schreibe ich meinen Namen in die Tasche.'],
    ['Der Abendkurs', 'Seit September mache ich einen Kurs am Abend. Der Kurs beginnt um sechs Uhr und dauert zwei Stunden. Wir sind zwölf Leute aus verschiedenen Ländern. Unsere Lehrerin spricht langsam und erklärt die Grammatik. Wir lesen Texte, hören Musik und sprechen viel. Zweimal pro Woche bekommen wir Hausaufgaben. Ich schreibe die neuen Wörter in ein Heft und wiederhole sie am Wochenende. Im Dezember haben wir eine Prüfung. Ich muss noch mehr üben, besonders beim Schreiben. Aber ich verstehe jetzt viel mehr als am Anfang und kann mit meinen Nachbarn sprechen.'],
    ['Der Markt', 'Am Samstag gehe ich immer auf den Markt. Dort kaufe ich Obst, Gemüse, Brot und Käse. Die Preise sind besser als im Geschäft und die Sachen sind frischer. Heute habe ich Äpfel, Tomaten und Kartoffeln gekauft. Die Verkäuferin war freundlich und hat mir einen Salat geschenkt. Ich habe mit Karte bezahlt und zehn Euro bezahlt. Danach habe ich noch Blumen für meine Mutter gekauft. Auf dem Markt treffe ich oft meine Nachbarn, und wir sprechen ein paar Minuten. Um zwölf Uhr bin ich wieder zu Hause und koche das Mittagessen.'],
    ['Das Telefon', 'Gestern habe ich drei Mal telefoniert. Beim ersten Mal war es meine Schwester, sie wollte am Sonntag kommen. Beim zweiten Mal war es die Praxis, ich habe einen Termin am Dienstag um zehn Uhr. Beim dritten Mal war es ein Mann, der eine Wohnung sucht. Ich habe ihm die Adresse gegeben und gesagt, dass er am Abend anrufen kann. Danach habe ich eine Nachricht für meinen Mann geschrieben. Er war nicht zu Hause und hat sein Telefon nicht gehört. Am Abend hat er zurückgerufen und wir haben lange gesprochen.'],
    ['Das Geschenk', 'Meine Freundin hat bald Geburtstag. Ich habe lange überlegt und dann ein Buch gekauft. Sie liest gern, deshalb passt das Buch gut. Meine Mutter hat gesagt, dass Blumen auch schön sind. Zuerst habe ich eine Karte geschrieben, danach habe ich das Buch in ein Papier gemacht. Am Samstag fahren wir mit dem Bus zu ihr. Sie wohnt in einem Dorf, die Fahrt dauert eine Stunde. Ich habe noch einen Kuchen gekauft. Ich hoffe, dass sie sich freut und dass das Wetter gut ist.'],
            ['Der Nachbar', 'Unser Nachbar hört jeden Abend laute Musik. Ich habe zwei Wochen nichts gesagt. Dann habe ich ihn am Abend besucht und gesagt: Bitte nicht so laut, ich muss am Morgen früh aufstehen. Er hat sich entschuldigt und die Musik nicht mehr so laut gemacht. Danach war eine Woche Ruhe. Am Freitag war es wieder laut, weil seine Freunde da waren. Am Sonntag habe ich eine Nachricht geschrieben. Am Sonntag hat er mir Kaffee gebracht und wir haben zusammen gesessen. Jetzt verstehen wir uns besser und er ruft vorher an.'],
    ['Die falsche Karte', 'Am Montag habe ich eine Fahrkarte gekauft, aber sie war falsch. Ich wollte nach Frankfurt fahren und habe eine Karte für den Bus genommen. Im Zug hat der Mann gesagt, dass die Karte nicht gilt. Ich musste eine neue Karte kaufen und zwanzig Euro bezahlen. Das war teuer, aber ich habe etwas gelernt. Danach habe ich am Schalter gefragt und die Frau hat mir alles erklärt. Am Abend habe ich die Karte meinem Bruder geschenkt, er fährt oft mit dem Bus. In der nächsten Woche kaufe ich die Karte im Internet.'],
        ['Das Rezept', 'Heute habe ich für meine Familie das Essen gemacht. Zuerst habe ich das Gemüse gewaschen und klein gemacht. Dann habe ich Öl in einen Topf getan und das Gemüse dazu. Danach habe ich Wasser, Salz und Pfeffer genommen und alles zusammen warm gemacht. Nach zwanzig Minuten war das Essen fertig. Meine Kinder haben geholfen und die Teller auf den Tisch gestellt. Wir haben zusammen gegessen und über den Tag gesprochen. Am Abend habe ich den Rest in den Kühlschrank gestellt. Morgen esse ich den Rest mit Brot zur Arbeit.'],
    ['Das Fest zu Hause', 'Am Samstag haben wir zu Hause gefeiert. Meine Tochter ist zwölf Jahre alt geworden. Ich habe am Morgen einen Kuchen und einen Salat gemacht. Meine Mutter hat Getränke mitgebracht und mein Bruder hat Musik gespielt. Um vier Uhr sind die Gäste gekommen. Die Kinder haben im Garten gespielt und die Erwachsenen haben Kaffee getrunken. Am Abend haben wir gegessen und Fotos gemacht. Um zehn Uhr sind alle nach Hause gegangen. Danach haben wir die Küche geputzt. Es war ein langer Tag, aber sehr schön.'],
        ['Die geschlossene Stelle', 'Auf dem Weg zur Arbeit ist die Straße geschlossen. Dort wird gebaut und der Bus fährt nicht. Am Montag habe ich zehn Minuten gewartet und bin dann zu Fuß gegangen. Ich bin zu spät gekommen und mein Chef war nicht zufrieden. Am Dienstag habe ich einen anderen Weg genommen. Ich bin mit dem Fahrrad gefahren, das war schneller. Die Baustelle dauert noch vier Wochen. Meine Kollegen haben mir gesagt, dass ein kleiner Weg hinter dem Park offen ist. Seit Mittwoch komme ich wieder pünktlich.'],
    ['Der Hund', 'Unsere Nachbarn haben einen Hund. Er ist schon alt und sehr freundlich. Jeden Morgen gehe ich mit ihm in den Park, weil die Nachbarn früh zur Arbeit fahren. Der Hund läuft gern und spielt mit den Kindern. Zu Hause wartet er vor der Tür und will Wasser. Am Wochenende gehen wir zusammen an den See. Dort schwimmt er und ich lese ein Buch. Im Winter bleibt er lieber im Haus. Meine Tochter hat Angst vor Hunden, aber er ist ruhig und tut nichts. Jetzt mag sie ihn sehr.'],
    ['Der kleine Test', 'Gestern haben wir in der Schule einen Test geschrieben. Es gab zwanzig Fragen und ich hatte nur eine Stunde Zeit. Die ersten Fragen waren leicht, aber die letzten zwei waren schwer. Ich habe einen Fehler gemacht und ein Wort vergessen. Nach dem Test habe ich mit meiner Lehrerin gesprochen. Sie hat gesagt, dass ich mehr lesen muss und dass die Grammatik noch nicht gut ist. Am Abend habe ich die Fehler noch einmal gemacht und die Wörter in mein Heft geschrieben. In zwei Wochen schreiben wir den nächsten Test.'],
    ['Der zweite Schlüssel', 'Am Sonntag habe ich meinen Schlüssel verloren. Ich war im Park und danach beim Bäcker. Zu Hause habe ich in allen Taschen gesucht, aber der Schlüssel war weg. Zum Glück hat meine Schwester einen zweiten Schlüssel. Sie hat mir die Tür geöffnet und wir haben zusammen Tee getrunken. Am Montag habe ich einen neuen Schlüssel gemacht. Das hat fünfzehn Euro gekostet. Jetzt habe ich drei Schlüssel: einen für mich, einen für meine Schwester und einen beim Nachbarn. So kann das nicht wieder passieren.'],
        ['Die Werkstatt und die Wohnung', 'Unsere Wohnung wird renoviert. Der Haushalt ist voll: Ich trage das Geschirr in den Schrank, trage die Pflanze zum Fenster und koche Bohnen im Topf. Die Schere liegt auf dem Tisch, die Reinigung macht die Bluse sauber. Die Werkstatt nebenan repariert die Maschine, das ist dringend, und die Werkstatt am Hof gehört der Vermieterin. Wir wollen sparen, deshalb kaufen wir preiswerte Möbel, aber die Qualität ist wichtig. Der Service im Laden ist gut und das Produkt günstig, einen Kredit brauchen wir nicht. Der Lärm stört uns manchmal, doch der Stress ist klein: Wir schaffen das. Endlich ist alles fertig. Wir müssen noch auspacken, ein Nachbar hilft beim Tragen, und im Juni wollen wir einziehen.'],
            ['Wer wohnt in unserer Straße?', 'In unserer Straße wohnen viele Berufe. Im ersten Haus arbeitet ein Arzt, seine Schwester ist Lehrerin. Daneben wohnt ein Musiker mit seiner Frau, einer Studentin. Der Bäcker öffnet um fünf, der Koch kocht im Lokal an der Ecke, und die Verkäuferin verkauft Schuhe. Ein Techniker repariert Fahrräder, daneben arbeitet ein Mechaniker in der Werkstatt. Oben wohnen ein Fahrer und ein Sänger, im Keller proben ein Musiker und eine Sängerin. Der Lehrer spielt im Theater, der Student im Film. Ein Doktor arbeitet im Krankenhaus, eine Rentnerin sitzt im Garten und trägt die Blumen ins Haus. Ein Kellner fehlt noch.'],
            ['Mein Stundenplan', 'Mein Stundenplan ist voll: Am Morgen habe ich Englisch, danach Kunst und Sport. Musik habe ich am Nachmittag, und Geschichte macht mir Spaß. Die Pause ist um zehn Uhr, dann esse ich ein Brot. Sprachen lerne ich gern. Meine Kenntnisse in Englisch sind gut, aber ich muss noch üben. Der Lehrer sammelt das Geld für die Reise, und ich notiere jeden Fehler in einer Notiz.'],
        ['Computer und Internet', 'Ich habe einen neuen Laptop und ein Tablet. Auf der Homepage der Schule muss ich Dateien herunterladen. Das Mobiltelefon ist immer dabei, und ein E-Book lese ich abends im Bett. Ich chatte mit Freunden, surfe im Internet und schreibe in meinem Blog über Bücher. Mein Passwort ist lang, das ist wichtig. Manchmal mache ich ein Quiz oder rate bei einem Rätsel mit. Der Kontakt zu meiner Familie ist so einfach: Wir wollen Fotos austauschen und oft telefonieren.'],
            ['Ferien in der Schweiz', 'In den Ferien fahren wir in die Schweiz. Am Tag sind es 25 Grad, nachts ist es kühl. Mein Koffer ist 60 Zentimeter lang und 20 Kilogramm schwer. Ich habe Schweizer Franken gewechselt, ein Kaffee kostet fünf Franken und achtzig Rappen. Drüben am Bahnhof treffe ich einen Mann; er arbeitet bei der Post und muss jeden Morgen die Post austragen. Heute geht er mit mir hin und her durch die Stadt, dann laufen wir vorwärts zum See. Die Kinder spielen am Wasser, ein Tier schwimmt in die kleine Bucht. Jetzt sind wir müde. Der Zug ist weg, wir müssen mit dem Bus zurückfahren und kommen erst um zehn Uhr zurück. Das war trotzdem super!'],
            ['Der neue Computer', 'Mein alter PC war zu langsam, der neue steht direkt neben dem Fenster. Eigentlich wollte ich nur einen Drucker, aber einige Programme waren notwendig: ein Programm zum Schreiben, eines für Fotos, eines für Musik. Ich habe deutlich gesagt: Bitte einfach halten! Jetzt schreibe ich Briefe, E-Mails und Texte, z. B. einen Text für Deutsch, d. h. ich lerne und arbeite mit dem gleichen Gerät. Das WC im Büro ist besetzt, deshalb arbeite ich heute zu Hause. Jeden Abend sitze ich hier, sogar am Sonntag. Überall ist Lärm, das muss ich unbedingt ändern, sonst brauche ich einen größeren Tisch. Das Gerät ist nicht billig, aber gut.'],
            ['Meine Lieblingssachen', 'Mein eigenes Zimmer mit einem einzelnen Tisch ist mein Ort. Einige Sachen sind alt und ein bisschen hässlich, das Sofa ist furchtbar, und der Film gestern war langweilig. Blöd und dumm finde ich nur, dass das Lernen manchmal schwierig ist. Meine Freunde sind verschieden: der eine lernt mit Musik, die andere lernt ruhig. Beim Prüfen bin ich vorsichtig, wahrscheinlich zu vorsichtig. Ich mache wenigstens eine Stunde Pause am Tag, mindestens dreißig Minuten. Ob das Wetter gut oder schlecht ist, ist mir wurscht. Tschüs, bis morgen!'],
            ['Zahlen und Zeiten', 'Erstens lerne ich jeden Tag, zweitens übe ich laut, danach schreibe ich Sätze und höre Radio. Ich lese viermal in der Woche. Ich zähle: hundert, zweihundert, bis tausend. Außer Deutsch spreche ich Arabisch und Englisch. Ich wohne außerhalb der Stadt, und nirgends gibt es so viele Bäume wie hier. Wenn ich einen Fehler mache, gehe ich zum Anfang zurück und laufe die zwei Kilometer noch einmal. Das letzte Mal habe ich zwei Stunden gelernt, das war total viel. Ein anderes Mal habe ich nur zehn Minuten geschafft, auch das ist gut.'],
            ['Das Festival in der Stadt', 'Am Donnerstag beginnt unser Fest. Rund zweihundert Leute kommen, ca. fünfzig helfen beim Bauen. Der Club am Markt macht heute Abend Musik. Für uns heißt das: erst helfen, dann feiern. Wer müde ist, kann früher nach Hause zurückgehen; die anderen laufen den Weg am Fluss zurück, denn zurücklaufen ist kürzer als der Bus. Am Sonntag wollen alle zusammen zurückkommen. Ein Comic kostet fünf Euro. Rund um den Bahnhof ist heute viel los.'],
            ['فصل في فرايبورغ', "Sara hat ein Stipendium für ein Jahr in Freiburg bekommen. Die Universität verlangt eine Übersetzung ihrer Zeugnisse und eine Erlaubnis für den Kurs. Die Mail war kurz: ohne Übersetzung keine Erlaubnis. Sie lernt unterwegs im Zug und ist den ganzen Tag unterwegs. Ihr Zimmer ist klein, aber es hat ein eigenes Regal. Vorne am Fenster steht ein Klavier. Das Klavier kommt von dort, wo ihre Großmutter gemietet hat. Im Winter ist es windig, und ihr Regenschirm liegt immer im Mantel. Ihr Nachbar regt sich schnell über Kleines auf. Sie will sich nicht aufregen und sagt nichts. Dafür braucht sie Ruhe, dagegen hilft nur Übung. Sie singt einzeln jedes Stück, erst langsam, dann schneller. Ihre Kenntnis des Deutschen wird mit jeder Woche besser. Nach dem Kurs ist sie fit und erzählt einen Witz. Ihr Nachbar findet den Witz witzig. Eines Tages streiten sie darüber, wer das Klavier benutzen darf. Am Ende ist es beiden egal, und sie lachen zusammen."],
  ].map((r, i) => text('a2-r' + (i + 1), 'A2', r[0], r[1]));
  const B1 = [
    ['Arbeit und Zeit', 'Einerseits spart die kurze Woche Zeit, andererseits fehlt dann Geld. Ich finde einen Kompromiss besser als ein absolutes Ja oder Nein. Zum Beispiel arbeite ich vier Tage und lerne am Freitag. So habe ich Zeit für die Sprache und verliere nicht die Hälfte meines Einkommens. Wichtig ist die Planung: Wer morgens früh anfängt, hat am Abend mehr Freiheit. Meine Kollegin arbeitet seit zwei Jahren so und ist zufrieden. Sie sagt, dass sie weniger Geld hat, aber ruhiger lebt. Ich habe dasselbe versucht und gemerkt: Die Grenze ist nicht die Zeit, sondern die Energie.'],
    ['Stadt ohne Auto', 'Der Vorteil ist die Ruhe, der Nachteil ist der Weg zur Arbeit. Nicht jede Stadt kann auf Autos verzichten, besonders wenn die Wege weit sind. Die Grenze ist der Ort, an dem kein Bus fährt. Ich habe drei Jahre kein Auto gehabt und bin mit dem Rad gefahren. Im Sommer war das angenehm, im Winter war es schwer. Heute fahre ich mit dem Zug und miete ein Auto, wenn ich es wirklich brauche. Eine Stadt muss zuerst den Bus besser machen, bevor sie das Auto verbietet. Sonst verlieren die Menschen, die am Rand wohnen.'],
    ['Spät lernen', 'Manche lernen am Abend, andere am Morgen. Ich habe beides versucht und weiß jetzt: Mein Kopf arbeitet am besten zwischen sechs und acht Uhr morgens. Am Abend bin ich müde und behalte nur die Hälfte. Trotzdem gibt es Tage, an denen ich erst nach der Arbeit Zeit habe. Dann lerne ich kurz, aber regelmäßig. Zwanzig Minuten täglich bringen mehr als zwei Stunden am Wochenende. Wichtig ist, dass ich nicht zwei Fächer gleichzeitig mache. Ich lerne zuerst die Wörter, dann die Grammatik, und am Ende lese ich einen Text.'],
    ['Die Versicherung', 'Nach dem Unfall habe ich einen Antrag bei der Versicherung gestellt. Der Betrag war niedriger als die Rechnung, deshalb habe ich nachgefragt. Die Antwort kam nach zwei Wochen: Es fehlten zwei Papiere. Ich habe die Papiere sofort geschickt und eine Bestätigung verlangt. Gleichzeitig habe ich mich bei der Beratung erkundigt. Dort hat man mir erklärt, dass ein Notfall anders behandelt wird als eine geplante Sache. Ich habe geduldig gewartet und am Ende die volle Summe bekommen. Mein Rat: Alles schriftlich, und jede Nummer notieren.'],
    ['Kaufen oder warten', 'Alles wird teurer, und viele kaufen sofort. Ich habe gelernt zu warten. Wenn ich etwas wirklich brauche, kaufe ich es nach einer Woche. In dieser Woche notiere ich den Preis und vergleiche zwei Geschäfte. Oft finde ich einen Rabatt oder ein besseres Produkt. Beim letzten Mal habe ich so fünfzig Euro gespart. Natürlich geht das nicht bei allem: Medikamente, Miete und Strom kann man nicht verschieben. Aber bei Kleidung und Technik hilft das Warten. Die Frage ist nicht, ob ich es will, sondern ob ich es brauche.'],
    ['Der Verein', 'Seit einem Jahr bin ich in einem Verein und trainiere dort zweimal pro Woche. Am Anfang kannte ich niemanden und war unsicher. Nach drei Wochen habe ich zum ersten Mal gefragt, ob ich dabei sein darf. Der Trainer hat sofort ja gesagt und mir die Regeln erklärt. Heute bin ich fest dabei und helfe den Neuen. Was mir gefällt: Es geht nicht nur um Sport, sondern auch um die Sprache. Im Verein spreche ich mehr Deutsch als im Kurs. Und wenn ich müde bin, sagen alle: Komm trotzdem! Das ist der Vorteil eines Vereins.'],
    ['Zwei Züge', 'Der erste Zug fährt um sechs Uhr und kommt pünktlich an. Der zweite Zug ist billiger, hat aber oft Verspätung. Ich habe beide Wege versucht und vergleiche sie noch heute. Wenn ich einen Termin am Morgen habe, nehme ich den ersten. Wenn ich frei habe, nehme ich den zweiten und lese im Zug. Einmal sind wir drei Stunden gestanden, weil ein Baum auf der Linie lag. Seitdem schaue ich am Abend in die App und prüfe die Verbindung. Mein Kollege sagt: Wer Zeit hat, fährt billig; wer Zeit braucht, fährt früh.'],
    ['Nachricht und Meinung', 'Gestern habe ich im Radio eine Nachricht gehört, die mich geärgert hat. Der Sprecher hat eine Zahl genannt, aber die Quelle nicht erklärt. Ich habe danach dieselbe Information in zwei Zeitungen gelesen und verschiedene Zahlen gefunden. Das zeigt: Nicht alles, was man hört, stimmt gleichzeitig. Ich prüfe wichtige Sachen selbst und bilde mir dann eine Meinung. Meine Meinung darf falsch sein, aber ich muss sie begründen können. Deshalb frage ich: Wer sagt das, woher weiß er es, und was fehlt in der Nachricht?'],
    ['Die Beschwerde', 'Die Lieferung kam zu spät, und die Folge war ein verpasster Termin. Ich habe zuerst angerufen und ruhig gefragt, was passiert ist. Der Mitarbeiter hat sich entschuldigt und mir erklärt, dass ein Fahrzeug ausgefallen war. Danach habe ich eine Nachricht geschrieben, kurz und sachlich: Was bestellt wurde, wann es kam, was fehlt. Ich habe um eine Lösung gebeten, nicht um eine Erklärung. Nach zwei Tagen kam die Antwort: Ersatz und ein Rabatt. Mein Ton blieb ruhig, und das war der Grund für den Erfolg. Wer schreit, bekommt später eine Antwort.'],
    ['Zwei Wege', 'Man kann eine Sprache auf zwei Wegen lernen: im Kurs oder allein. Der Kurs gibt Struktur und Hilfe, aber er ist langsam. Wer allein lernt, ist schnell, doch die Fehler bleiben unsichtbar. Ich habe beide Wege verbunden: Montag und Mittwoch im Kurs, an den anderen Tagen zwanzig Minuten für mich. So hatte ich dasselbe Ziel wie meine Kollegen, aber mehr Zeit zum Sprechen. Wichtig bleibt die Kontrolle: Ich nehme eine Aufnahme auf und höre sie am Sonntag. Was ich höre, ist die Wahrheit über meinen Weg.'],
    ["شقة جديدة وساحتها", "Wir ziehen im Mai in eine andere Wohnung. Die alte war möbliert, die neue ist leer. Im Treppenhaus riecht es nach Farbe, und im Flur liegt noch Staub. Die Hausmeisterin zeigt uns den Kasten für die Fahrräder und die Steckdose neben der Badewanne. Draußen gibt es einen kleinen Rasen und einen Hügel hinter dem Haus. Mein Nachbar baut ein Regal und braucht Hammer, Zange, Nagel und anderes Werkzeug. Ich hänge die Mappe mit den Papieren an die Wand und lege ein Kissen auf den Stuhl. Der Lift ist alt und bleibt manchmal stehen; dann nehmen wir das Stiegenhaus. Am Briefkasten steht noch der Name der Vormieterin. Wegen einer Baustelle gilt eine Umleitung, und die Einfahrt ist gesperrt. Unsere Nachbarin hat einen Bauernhof am Stadtrand und holt uns am Wochenende mit dem Auto ab. Unser Wohnort bleibt derselbe Stadtteil, deshalb ist der Weg zur Arbeit kurz. Übrigens kommt die Hausmeisterin jeden Dienstag, und sie achtet darauf, dass nichts im Hof liegt."],
    ['Bewerbung und erste Woche im Betrieb', 'Seit Januar suche ich eine Arbeitsstelle. Die Firma verlangt eine Arbeitserlaubnis und ein Diplom; nach meiner Matura haben sie nicht gefragt. Im Terminkalender der Chefin war kein Platz, also schickte ich eine kurze Mappe mit Zeugnissen. Der Kursleiter half mir beim Referat über meine Erfahrung, und ich erfüllte jede Bedingung. Gestern stellte mich ein Betrieb ein: Ich bin jetzt Lehrling im ersten Monat, und die Gewerkschaft vertritt mich. Der Betriebsrat erklärte die Regeln, und ich muss sie genau beachten. Beim ersten Gehalt berechnete das Büro die Mehrwertsteuer falsch; nach einer Mahnung bekam ich das Geld. Mein Chef duzt mich, die Kundin siezt er. Eine Kollegin betreut die Neuen und begleitet sie zur Versichertenkarte, die jeder benötigt. Am Eingang begegne ich dem Chef, der mich freundlich grüßt. Nach der Lehre trete ich in den gleichen Betrieb ein, wenn alles gut läuft. Die Firma bildet jedes Jahr zwei Lehrlinge aus und eröffnet im Herbst eine zweite Filiale; dann besprechen wir den Plan und legen die Termine fest.'],
    ["Beim Arzt und danach", "Im Februar bin ich stark erkältet. Zuerst ist es nur ein Schnupfen, dann tut das Knie weh und der Muskel im Rücken ist hart. Ich schwitze in der Nacht und friere am Morgen. In der Ordination wartet eine Patientin mit ihrer Tochter, und die Pflegerin misst meine Temperatur. Die Ärztin sagt, ich muss mich ausruhen, und verschreibt ein Schmerzmittel. Gegen die Grippe gibt es im Herbst eine Spritze. Meine Mutter nimmt jeden Tag eine Pille gegen den Blutdruck; sie ist siebzig und ziemlich fit. Beim Staub saugen läuft meine Nase, denn Staub und Milben sind ein Problem. In der Klinik nebenan blutet ein Mann nach einem Unfall, und ein Krankenwagen steht vor der Tür. Wenn die Knochen alt werden, sind sie nicht mehr so fest. Meine Schulter war nach dem Umzug eine Woche lang fast taub. Für eine Schwangerschaft gibt es eigene Kontrollen. Ich trinke Tee mit Honig, schlafe lange und gehe erst wieder arbeiten, wenn der Körper ruht."],
    ["Unterwegs in der Stadt", "Am Montag stehe ich im Stau. Ein Laster, ein Motorrad und die Tram blockieren die Fahrbahn, und hinter mir hupt jemand. Ich bremse, weil ein Fußgänger über die Einbahnstraße geht; die Fußgängerzone beginnt erst hinter der Kreuzung. Ein Kraftfahrzeug darf hier nicht halten, deshalb winke ich dem Radfahrer, der mich überholt. Auf dem Perron am Hauptbahnhof warten die Passagiere schon seit zwanzig Minuten. Mein Fahrzeug braucht Benzin, also fahre ich zur Tankstelle und parkiere dort. Den Führerausweis habe ich immer dabei. Die Geschwindigkeit war heute niedrig, denn die Geschwindigkeitsbeschränkung gilt auch nachts, und wer zu schnell fährt, verliert Punkte. Im Notfall zeigt der Notausgang nach hinten. Ich fahre lieber mit der Tram, aber heute war sie voll. Unterwegs denke ich an die Liste im Büro, die ich noch erledigen muss."],
    ['Einkaufen und kochen', 'Am Samstag gehe ich hungrig auf den Markt. Der Fleischhauer hat kein Hackfleisch mehr, also kaufe ich Poulet für das Menü. Für die Vorspeise nehme ich eine Semmel mit Essig und Öl, als Nachspeise gibt es Schlagobers mit Aprikosen. Die Marille, wie die Aprikose in Österreich heißt, ist jetzt reif. Ich brauche noch Mehl, Karotten und Möhren für den Kloß; ein Knödel schmeckt mit brauner Soße besser. Zuhause heize ich den Backofen vor und lege das Poulet in die Pfanne. Das Gemüse kommt aus dem Garten, deshalb ist es frisch und mild. Meine Schwester ist sparsam: Sie kauft nur, was sie wirklich braucht, und nichts kommt in den Müll. Im Imbiss an der Ecke zahle ich mit Karte und gebe kein Trinkgeld, weil die Bedienung nicht freundlich war. Der Erdapfel aus dem eigenen Garten ist kleiner, aber besser. Übrigens passt zu allem eine Frucht der Saison.'],
    ["Gewitter über dem Hügel", "Im Juli ist die Hitze kaum auszuhalten. Zuerst ist der Himmel grau, dann blitzt es über dem Hügel, und der Donner kommt näher. Es donnert so laut, dass die Fenster zittern, und plötzlich hagelt es. Die Wiese hinter dem Haus ist danach ganz nass, und die Wärme bleibt in den Steinen. Ich friere trotzdem, weil der Wind kalt ist. Am nächsten Morgen trocknen die Sachen auf der Leine, und der Boden ist glatt. Der Weg zum Garten ist schmal und flach, kein Problem. Mein Nachbar hat einen riesigen Baum; seine Früchte sind rot, aber giftig, das weiß hier jeder. Wenn die Sonne wieder scheint, arbeiten wir im Garten weiter. Gewöhnlich regnet es hier im Mai, diesmal aber erst im Juli. Ich habe übrigens noch nie einen so starken Blitz gesehen. Nachher sitzen wir draußen und trinken Tee, bis es dunkel wird."],
    ["Am Bankschalter", "Mein Girokonto ist seit Jahren bei derselben Bank. Heute will ich Geld am Geldautomaten holen, aber die EC-Karte funktioniert nicht; auch der Bancomat neben der Tür zeigt einen Fehler. In der Schweiz heißt das Gerät Bankomat, in Österreich Bankomatkarte, und offiziell spricht die Bank von einer Chipkarte. Ich fülle einen Auftrag aus: eine Einzahlung von zweihundert Euro in Münzen. Die Bankleitzahl steht auf dem Formular, und die Beraterin erklärt die Zinsen. Meine Einnahmen sind klein, deshalb prüfe ich jede Ausgabe persönlich. Die Regeln sind rechtlich klar, aber nicht überall einheitlich. Für den Kredit verlangt die Bank eine Bestätigung meiner Mieterin. Ich lege die Quittung in eine Kassette, denn Papier ist haltbarer als ein Foto. Verantwortlich für den Fehler war am Ende die alte Karte. Spätestens am Freitag soll die neue da sein; bisher habe ich nur eine Bestätigung per Post bekommen."],
    ["Computer, Netz und Büro", "Unser Büro arbeitet fast komplett elektronisch. Vor dem Herunterfahren speichere ich alles, und am Abend dauert das Hochladen lange; die Festplatte ist fast voll, und der Monitor flackert. Der Lautsprecher für die Konferenz hängt an der Wand, und das Netzwerk ist langsam, weil alle gleichzeitig online sind. Meine Kollegin macht eine Recherche für eine Reportage und schreibt ein Inserat für eine Stelle. Die Reklame auf der Seite ist laut und bunt, und manche twittern während der Sitzung. Auf der Mobilbox habe ich drei Nachrichten; eine ist technisch nicht zu verstehen. Die Fotografie für den Bericht macht ein Kollege, weil er kreativ ist und ein gutes Auge hat. Virtuelle Treffen sparen Zeit, aber individuelle Gespräche fehlen. Trotzdem ist die Arbeit ordentlich organisiert, und jeder ist zuverlässig. Zunächst prüfen wir die Daten, dann schicken wir den Text. Übrigens kann jeder jederzeit ins Archiv schauen; das System ist mobil und sicher."],
    ['Brief an die Versicherung', 'Sehr geehrte Damen und Herren, ich schreibe wegen meiner neuen Tätigkeit. Meine Firma kündigt eine zweite Stelle an und beschäftigt bald mehr Personal. Ich bitte Sie, meine Daten zu überprüfen: Mein Personenstand hat sich geändert, und im Bereich der Beiträge hat das Büro den Betrag falsch berechnet. Bitte ergänzen Sie die Unterlagen und legen Sie den neuen Termin fest. Ich habe alle Belege aufgeschrieben und eingesetzt; die Verbindung zwischen Antrag und Antwort ist bisher nicht klar. Mein Nachbar hat mir geraten, die Police nicht zu verwechseln. Ich habe eine Kopie erstellt, das Original besorgt und in einen Ordner aufgenommen. Wenn Sie Fragen haben, rufen Sie mich an. Ich habe übrigens ein Grundstück bekommen und muss die Umgebung des Hauses neu einrichten; auch die Entsorgung von altem Papier ist geregelt. Bis dahin verlasse ich mich auf Ihre Antwort. Mit freundlichen Grüßen, Sara Ben Ali.'],
    ['Auf dem Land', 'Seit zwei Jahren wohnen wir auf dem Land, und der Alltag ist ruhiger als in der Stadt. Alltäglich ist es hier still, manchmal fast zu still: Wer allein lebt, wird leicht einsam. Das Haus war ursprünglich ein Lager, und der Umbau war körperlich schwer. Ehrlich gesagt war der Plan nicht ideal; ich habe ihn ernsthaft bereut. Trotzdem ist der Garten hübsch, und das Klima ist für die Gesundheit geeignet. Der Nachbar ist traditionell, aber tolerant, und seine Frau ist politisch aktiv. Ökologisch ist unser Leben nicht perfekt: Zwar trennen wir den Müll, aber die Heizung ist alt. Auf dem Land ist fast alles traditionell, und viele Regeln sind sozial gewachsen, nicht offiziell. Manche sagen, es sei unheimlich hier, andere finden es einfach anders. Ich halte die Angst für vergeblich. Übrig bleibt die Frage, ob wir hier alt werden wollen; diese Entscheidung ist persönlich und politisch gleichzeitig — also offen.'],
    ['Strom und Wärme', 'Einerseits ist unser Strom billig. Anderseits bezahlen wir die Folgen später. Inzwischen ist klar, dass die Preise dauernd steigen; sie gehen kaum noch aufwärts, sondern nur nach oben. Neben dem Fluss entlang stehen alte Anlagen, und das Kraftwerk am Rand der Stadt läuft rund um die Uhr. Indem wir weniger heizen, sparen wir wirklich, nicht bloß auf dem Papier. Höchstens die Hälfte der Wärme geht dann verloren; das ist mein Eindruck. Gar nichts zu tun wäre mir zu einfach. Ich sage jedoch: Verbote allein helfen nicht, und ein Verbot ohne Geld ist sowieso schwach. Schließlich ist die Politik für die Umwelt keine Frage von Meinungen, sondern von Zahlen. Vorhin habe ich die Zahlen der Umgebung gelesen: Nirgendwo in der Region wurde so viel gebaut wie hier. Wenn wir nicht irgendwann handeln, zahlen wir ewig. Umgekehrt gilt ebenfalls: Wer heute investiert, spart morgen. Das ist völlig klar und wird gleichfalls in anderen Ländern so gesehen.'],
    ["Ausbildung in Zahlen", "In diesem Bereich arbeiten viele Wissenschaftler und Wissenschaftlerinnen. Sie beobachten, wie Betriebe ausbilden, und überlegen, ob das Angebot ausreicht. Wer sich beteiligt, muss festlegen, welche Tätigkeit zu welchem Beruf passt. Die Firmen stellen jedes Jahr Lehrlinge ein; wer eintritt, soll den Beruf genießen, aber auch das Gewissen fragen, ob die Arbeit zu ihm passt. Manche Betriebe behindern die Ausbildung, weil Betreuer fehlen. Andere übertreiben: Bei ihnen steht alles fest, bevor der Vertrag unterschrieben ist. Häufig fehlt es an Zeit, nicht an Willen. Fest steht jedenfalls, dass ein Abschluss ohne Praxis schwach bleibt. Ich habe mir überlegt, einen Kurs zu besuchen, um meine Kenntnisse zu erweitern. Wer nur zuhört und nie fragt, verwechselt Prüfung und Beruf. Deshalb schreiben wir jede Woche einen kurzen Bericht und besprechen ihn danach. So bleibt Wissen nicht theoretisch, sondern wird sichtbar."],
    ['Wohnungssuche mit Hindernissen', 'Die Stimmung in unserem Haus ist ruhig, und mit der Nachbarin ist eine echte Freundschaft entstanden. Umso schwerer war die Entscheidung, ein anderes Grundstück zu suchen. Die Umgebung bleibt dieselbe: Die Verbindung zum Zentrum ist gut, und im Bereich der Schulen gibt es ein ausgezeichnetes Angebot. Trotzdem war die Suche schwer. Eine Anzeige klang ideal, aber der Preis war relativ hoch, und die Bilder waren künstlich hell gemacht. Ein zweites Angebot war regional und günstig, doch illegal gebaut: keine Erlaubnis, keine Unterlagen. Das war verdächtig, und ich habe den Vertrag nicht unterschrieben. Eine Bekannte hat mir dann geholfen; ihre Tätigkeit ist der Verkauf von Wohnungen, und sie arbeitet berufstätig und treu bei derselben Firma. Am Ende haben wir etwas Kleines gefunden, mit einem schlanken Plan und einem Balkon, der senkrecht über dem Hof liegt. Mutig war nur der Kredit, alles andere war Glück.'],
    ['Das große Spiel', 'Beim großen Spiel unserer Stadt war die Stimmung zuerst locker, dann ernst. Zwei Mannschaften spielten maximal gut, und das Ergebnis blieb bis zum Schluss unentschieden. Die Leitung des Spiels traf jede Entscheidung spitz, aber nicht immer gerecht; manche fanden sie schuldig, andere bloß streng. Statistisch war das Spiel ausgeglichen: Die Zahl der Chancen war relativ klein, und die Fans waren unglaublich geduldig. Eine Sportlerin war besonders schlank und schnell; ihre Technik wirkte speziell, fast künstlich, doch sie war sauber. Nach dem Schlusspfiff war es still — stumm wie in einem leeren Saal. Ich fand die Reaktion seltsam, denn niemand feierte. Später sagte ein Trainer, der Sport sei hier populär, aber politisch schwach unterstützt. Er hat deshalb recht, weil der Verein jedes Jahr um Geld kämpft. Nächste Woche wird das nächste Spiel angekündigt, und dann sehen wir, ob die Stimmung positiv bleibt.'],
    ["Ein Wochenende an der Küste", "Mit der Eisenbahn fahren wir an die Ostsee, weil die Nordsee im Herbst zu windig ist. Die Küste ist flach, und hinter den Dünen liegt ein schmaler Streifen Gras. Der Sand ist kalt, aber die Luft riecht nach Salz. Am Abend sitzt der Mond tief über dem Wasser, und unser Schatten wird lang. Im Speisewagen haben wir nur einen Kaffee getrunken und die Botschaft gelesen, die uns die Vermieterin geschickt hat. Hinter dem Dorf steigt der Weg in ein kleines Tal, und die Erde ist dort dunkel und weich. Auf einem Stein am Rand sitzt eine Frau und zeichnet einen Kreis ins Heft. Die Landwirtschaft hier lebt von Obst und Milch; normalerweise kommen im Sommer mehr Gäste. Ein Feuerzeug haben wir vergessen, deshalb fragen wir im Laden. Die Gebrauchsanweisung für das Boot liegt im Katalog, aber wir leihen lieber nichts. So verbringen wir zwei ruhige Tage."],
    ['Der Dienstag', 'Am Dienstag kommt die Müllabfuhr sehr früh. Wenn wir den Schmutz nicht trennen, wird aus der Küche schnell ein Problem, und aus dem Problem Umweltverschmutzung. Der Alarm im Treppenhaus war letzte Woche umsonst; ein Rohr war undicht, und das Backrohr hat dabei auch nicht funktioniert. Beim Einschalten des Lichts sehen wir den Fleck an der Wand. Im Handel hört man oft, alles sei pauschal erledigt, aber zu Hause zählt jede kleine Sache. Meine Brieftasche habe ich in der Tasche, das Taschentuch in der Jacke und die Zahnpasta im Kasten. Beim Springen über den nassen Hof ist mir der Hut vom Kopf gefallen. Meine Nachbarin umarmt mich und lacht; ihre Laune ist an solchen Tagen besser als meine. Sie sagt: Kein Grund zum Schreck. Also räumen wir gemeinsam auf, und am Abend ist die Küche wieder sauber.'],
    ['Musik im Dorf', 'Jeden Sommer spielt ein kleines Orchester im Hof der alten Schule. Eine Frau aus dem Dorf spielt Flöte, und ihre Tochter singt; beide sind sehr musikalisch. In der Galerie neben der Kirche hängt ein Gedicht an der Wand, das ein Bauer vor hundert Jahren geschrieben hat. Die Tradition ist hier lebendig, und viele Gäste kommen aus anderen Ländern; das Fest ist interkulturell, ohne dass jemand das Wort benutzt. Ich zweifle manchmal, ob so ein kleines Dorf das jedes Jahr schafft. Meine Laune war am Anfang nicht gut, denn ich hatte Heimweh nach der Stadt. Doch dann hat mich der Klang erschreckt und gleichzeitig beruhigt. Die Überraschung war groß, als der Leiter der Stadt selbst eine Rede hielt. Manche hassen solche Feste, weil sie laut sind. Ich nicht: Ich habe die Ruhe nach dem letzten Ton festgehalten und im Heft aufgeschrieben. Am Ende standen alle im Kreis und klatschten.'],
    ["Sprachkurs und ein Brief", "Meine Freundin besucht einen Intensivkurs für Deutsch als Zweitsprache. Die Kursleiterin kommt aus Wien und spricht außer Deutsch noch zwei Fremdsprachen. Jeden Morgen bringt die Briefträgerin einen Briefumschlag mit Übungen, und danach geht meine Freundin in die Buchhandlung, um ein Wörterbuch zu kaufen. Weil ein Teil ihres Buches fehlte, verlangte sie Ersatz und bekam ihn sofort. Die Stadt verpflichtet alle neuen Einwohner zu einem Sprachkurs; das ist keine Strafe, sondern eine Hilfe. Ein Protest dagegen kam nur von wenigen. Ich habe die Aufgabe, jeden Abend dreißig Minuten zu lesen, und bisher halte ich mich daran, indem ich jeden Text zweimal aufnehme. Einmal habe ich die Übung vergessen und musste den Ersatz am nächsten Tag nachholen. So bleibt die Sprache nicht fremd, sondern wird alltäglich."],
    ['Beim Einzug', 'Die Wohnung liegt in der dritten Etage, und die Einrichtung ist noch nicht fertig. Der frühere Mieter hat die Vermietung über eine Agentur gemacht, und im Vertrag steht, dass ich dekorieren darf. Ich stelle den Fauteuil neben die Couch, hänge den Spiegel an die Wand und setze die Vase auf den Tisch. Die Garderobe im Flur ist zu klein für vier Mäntel. Aus den Schachteln nehme ich Teller, eine Dose und zwei Büchsen; den Rest trage ich in einem Sack zur Mülltonne, denn Dreck und Verpackung sollen nicht bleiben. Die Fläche des Balkons ist klein, und die Entfernung zum Aufzug stört mich nicht. Beim Putzen brauche ich Waschmittel, Zahncreme und eine Nadel für den Vorhang. Eine eckige Kommode steht schief, deshalb erhöhe ich sie mit einem Stück Holz. Mittlerweile weiß ich, wo der Schalter ist; die Erhöhung der Miete war im Vertrag klar genannt. Am Abend kommt die Nachbarin, und wir trinken Tee zwischen den halb leeren Kisten.'],
    ["Auf dem Markt und in der Küche", "Am Samstag kaufe ich Karotten, Pflaumen und Paradeiser; in Österreich heißt die Tomate Paradeiser. Der Metzger empfiehlt ein Hühnchen, und ich nehme Pilze, in Bayern Schwammerl genannt, sowie ein Henderl für die Suppe. Für das Frühstück gibt es Konfitüre, Margarine und Gebäck; ein Brötli in der Schweiz ist dasselbe wie eine Semmel. Ich brauche noch ein Gewürz, Rahm und Sahne, in Österreich Schlagrahm oder Obers, dazu Kakao und Limonade. Die Zutaten für das Dessert sind einfach: eine Glace, etwas Zucker und Obst. Meine Schwester ist Vegetarierin, deshalb koche ich vegetarisch und lasse das Fleisch roh im Kühlschrank. Salzig esse ich wenig, satt werde ich trotzdem. Am Nachmittag gibt es eine Jause, in Zürich ein Znüni und am Abend ein Zvieri. Im Büfett des Kaffeehauses stehen Kuchen und Torten. Ich mische die Soße vorsichtig und probiere sie; der Geschmack ist mild. In der Kneipe nebenan isst man billig, aber die Mahlzeit dort ist laut."],
    ['Unser Verein', 'Unser Verein hat eine eigene Sportart: Fußball. Im Stadion sind heute zweitausend Zuschauer, und die Serie der Siege ist lang. Der Profi und die Profisportlerin trainieren jeden Tag, und auch die Spielerin aus der zweiten Mannschaft kommt mit. Die Trainerin achtet auf Gymnastik vor dem Spiel, weil der Körper warm sein muss. Im Winter gehen wir ins Hallenbad, im Sommer zelten wir am See. Die Wanderung auf den Berg dauert vier Stunden, und danach machen wir ein Picknick auf der Wiese. Der Tierpark am Rand der Stadt ist ein Ziel für Familien; dort spielt kein Golf und kein Ballett, aber es gibt viel zu sehen. Der Rekord im Lauf steht seit drei Jahren, und der Kampf um den Titel bleibt offen. Die Teilnahme am Kurs kostet fünfzig Euro im Jahr, und jede Teilnehmerin bekommt ein kleines Spielzeug für die Kinder mit. Der Sportler aus dem Nachbardorf ist optimistisch, dass sein Verein das Turnier gewinnt.'],
    ["In der Stadt unterwegs", "Auf dem Gehsteig, in der Schweiz Trottoir und in Wien Gehsteig, stehen heute viele Menschen. An der Kreuzung achte ich auf die Vorfahrt und auf das Verkehrszeichen über der Ampel; wer zu schnell fährt, bekommt einen Strafzettel. Die Zone rund um die Schule ist ruhig, doch im Vorort gibt es keinen Kanal für das Regenwasser. Am Hafen legen die Schiffe an, und die Metropole wächst jedes Jahr. In unserem Quartier ist der Zugang zum Park frei, und das Zentrum ist städtisch und zentral gebaut; jede Wohnung ist zugänglich. Bevor ich losfahre, muss ich tanken, denn das Tempo auf der Autobahn kostet Benzin. Für die Übernachtung suchen wir ein Hotel, und die Rückkehr planen wir für Sonntag. Die Rückfahrt dauert drei Stunden, aber eine Rundfahrt über die Dörfer ist schöner. Das Velo, so heißt das Fahrrad in der Schweiz, steht am Bahnhof. Nach der Landung des Flugzeugs brauche ich eine Stunde zum Treffpunkt, weil der Transport der Koffer langsam ist. Ich transportiere nur einen Rucksack, und der Weg führt quer durch die Stadt."],
    ['Krank und wieder gesund', 'Eine Infektion mit einem Virus beginnt oft leicht. Die Medizin hilft nur, wenn man sie richtig nimmt; eine Therapie mit Tropfen und Vitaminen ist kein Ersatz für den Arzt. Im Spital wird heute operiert, und die Patientin ist nachher erschöpft und blass. Wer blind oder schwer krank ist, braucht Hilfe beim Essen, deshalb verpflegt die Klinik ihre Gäste. Der Notruf kam nachts: Ein Unfall mit zwei Verletzten, eines davon tödlich, war die Ursache des Einsatzes. Das Opfer lag auf der Straße, und die Kriminalpolizei sperrte die Spur. Meine Nachbarin ist süchtig nach Tabletten und nimmt ein Suchtmittel, das der Arzt nicht gegeben hat. Nach einer Woche braucht sie Erholung, und sie ernährt sich besser: viel Gemüse, wenig Zucker. Ich habe realisiert, dass die Gesundheit nicht selbstverständlich ist.'],
    ['Industrie und Institut', 'Unsere Industrie verkauft Maschinen und kauft Metall; der Einkauf ist teuer geworden, und die Konkurrenz aus anderen Ländern wächst. Der Prozess in der Fabrik ist genau festgelegt, und jede Methode wird geprüft. Ein neues Modell braucht Monate, und jeder Faktor zählt: Zeit, Geld und Personal. Die Kommunikation entscheidet über den Erfolg. Das Institut für Technik empfiehlt einen Kurs, und die Empfehlung gilt für alle. Im Büro kopiert der Kopierer langsam, und mit einem Kuli schreibe ich die Liste; auf dem Laufwerk lösche ich alte Dateien. Ein Magazin und der Verlag dahinter finanzieren die Werbung. Der Bedarf an Fachleuten ist groß, und die Firma garantiert jedem Studenten ein Praktikum. Die Beschäftigung mit Zahlen gefällt mir; finanziell ist die Stelle besser als die alte.'],
    ["Schule und Lernen", "Heute schreiben wir eine Klassenarbeit, in Österreich eine Schularbeit. Wer in Mathematik schwach ist, nimmt Nachhilfe, und nach dem Mittagessen in der Mensa lernen wir weiter. Ich schlage jedes neue Wort im Lexikon nach und unterstreiche die Regel; die Einführung in das Thema hat die Professorin selbst geschrieben. Die Literatur des Landes gehört zum Programm, und ein Schriftsteller kommt im Mai zu Besuch. In der Pause lese ich ein Märchen, das meine Schwester als Kind geliebt hat. Die Intelligenz allein reicht nicht: Man muss sich konzentrieren, und die Stufe des Kurses ist hoch. Der Nachwuchs fehlt in technischen Berufen, deshalb führt die Schule ein neues Fach ein und fügt Übungen in den Plan ein. Das Alphabet haben wir in der ersten Woche gelernt. Die Zeichnung an der Tafel zeigt den Aufbau eines Satzes."],
    ["Gefühle und Miteinander", "Mein Kollege war wütend, weil die Lieferung fehlte, und ich war zuerst ängstlich, dann fröhlich, als sie am Abend kam. Es war peinlich, dass ich den Namen der Kundin vergessen hatte; so etwas ist mir schon zweimal passiert, ich irre mich selten, aber heute ja. Der Chef kann wahnsinnig frech sein, wenn er müde ist. Heimlich habe ich das Geschenk vorbereitet, denn ich wollte meine Schwester nicht enttäuschen. Sie fürchtet sich vor dem Umzug, aber sie weigert sich nicht mehr. Wir müssen miteinander reden und voneinander lernen. Der Streik der Fahrer hat die Versammlung verschoben, und die Gewalt auf der Straße war zum Glück selten. Ich habe mich bei ihr entschuldigt und um Verzeihung gebeten; sie hat mir verziehen, und das Verständnis zwischen uns ist besser als vorher. Sie hat mir versprochen, dass wir zusammen feiern, und das Vergnügen war groß. Lächeln hilft mehr als Vorwürfe, und der Sinn des Tages ist nicht sinnlos, wenn man ihn teilt."],
    ["Bei der Behörde", "Auf dem Amt muss jede Person anwesend sein, auch die Angehörigen eines Kindes. Die Beamtin verlangt meinen Wohnsitz und den Zivilstand; beide stehen auf der Aufnahme des Antrags. Ich soll alles aufschreiben, was zur Betreuung gehört, und die Betreuerin der alten Dame bestätigt es schriftlich. Das Ehepaar im Korridor wartet schon lange, und der Bewohner aus dem ersten Stock hat seine Visitenkarte dabei. Für die Einzelheit brauche ich einen Stempel, und das Einschreiben kommt per Post. Die Geburt meines Neffen ist noch nicht eingetragen, deshalb ist die Frist bald fällig. Das Konsulat genehmigt die Unterlagen nur, wenn nichts fehlt, einschließlich des Geschlechts und der Staatsangehörigkeit. Die Integration von Migranten ist hier ein Thema, und die Migration der letzten Jahre ist in jeder Statistik zu sehen. Mein Antrag befindet sich in Prüfung, und die Gebühr ist begrenzt. Als Bürgerin habe ich gleiche Rechte, aber die Ausfahrt aus dem Hof ist untersagt."],
    ['Feste im Dorf', 'Im Feber beginnt der Fasching, und in der Schweiz heißt diese Zeit Fasnacht. Die Nachbarin näht ein Kostüm für ihre Tochter, und die Wirtin im Gasthaus macht den Saal schön. Am Sonntag grillieren wir hinter der Hütte, und die Gäste gratulieren der Heldin des Tages. Der Humor der alten Männer ist trocken, und der Dialekt klingt hier weicher als in der Stadt. Beim Fest im Kaffeehaus liest eine Frau aus dem Dorf historische Briefe vor; ein Denkmal an der Burg erinnert an dieselbe Zeit. Am Abend gehen die Jungen in die Diskothek, die Älteren in die Oper oder ins Studio des Theaters. Das Schaufenster im Salon nebenan zeigt Schmuck und Hüte. Vom Tourismus lebt die halbe Stadt: Im Sommer ist jede Terrasse voll, und die Gaststätte am See nimmt Reservierungen an.'],
    ['Tiere, Wetter und Natur', 'Unser Haustier, eine alte Katze, will jeden Morgen gefüttert werden; sie frisst wenig und beißt nie. Hinter dem Haus lebt eine Schlange, die im Gras verschwindet. Das Gebiet am Fluss ist wild, und im Gebirge beginnt der Ozean der Wolken. Wenn es hagelt, bleiben wir drinnen und hören die Wettervorhersage. Der Garten blüht im Mai, und Vögel fliegen zwischen den Blumen; ein Gift für Insekten benutzen wir nicht. Der Zünder und das Zündholz liegen im Kasten, aber Feuer machen wir nur beim Grillen. Aus Kunststoff, Leder und Stoff entstehen Taschen und Schuhe. Ein Vogel ist aus dem Zimmer geflohen, und die Flucht endete auf dem Dach. Nach der Katastrophe im letzten Jahr haben wir das Haus stärker gebaut. Die Linie zwischen Feld und Wald ist waagerecht gezogen.'],
    ['Das Radio', 'Das Medium, das ich am meisten nutze, ist das Radio. Eine Reporterin interviewt heute den Spezialisten für den Bau der Stadt, und seine Kollegin, eine Übersetzerin, übersetzt live. Die Unterhaltung am Abend ist kurz, aber stilistisch sauber. Die Unternehmerin erklärt, wie ihre Firma wächst; die Zahl der Mitarbeiterinnen steigt. Eine Hörerin schreibt, dass sie die Sendung vorliest, um Deutsch zu üben; eine Zuhörerin aus Wien ruft an und stellt eine Frage. Die Leserin und der Lerner finden dieselbe Stelle schwer. Die Leiterin der Zeitung, eine Richterin, war früher Politikerin. Das Symbol der Sendung ist ein alter Stempel. Für die Vertretung einer Kollegin suche ich die Rufnummer der Zeitung; der/die Serviceangestellte am Empfang nennt sie mir.'],
    ['Arbeit gesucht', 'Die Annonce im Netz sucht eine Aushilfe für den Sommer; ich lese die Annonce jeden Tag, damit ich nichts verpasse. Beruflich möchte ich in einem Büro arbeiten, und eine Lehrstelle wäre ein guter Anfang. Der Ingenieur und die Fachfrau leiten die Abteilung, und die Fachleute dort sind freundlich. Der Händler und die Händlerin im Erdgeschoss verkaufen Möbel; die Käuferin fragt nach dem Preis, der Käufer zahlt mit Karte. Nach der Entlassung eines Kollegen hat die Direktorin die Stelle neu gesucht. Die Anwältin prüft den Vertrag, bevor ich ihn anschaffe. Ich schicke meine Visitenkarte und die Rufnummer an die Unternehmerin, die das Gespräch führt. Eine Aushilfe wird schnell eingestellt, aber die Entlassung kommt manchmal genauso schnell.'],
    ['Sicherheit in der Stadt', 'In unserer Straße ist im Winter zweimal eingebrochen worden. Der Einbrecher kam über den Balkon, und der Einbruch war am Morgen sichtbar. Die Polizei konnte einen Täter festnehmen und einen zweiten verhaften; beide sitzen jetzt im Gefängnis, und das Gericht wird sie verurteilen. Wer stiehlt, wird bestraft, und wer flieht, wird gesucht. Bei der Flucht ist ein Radfahrer überfahren worden; zum Glück gab es kein zweites Unglück. Der Täter und seine Frau waren betrunken. Die Versicherung beschränkt die Zahlung, und verbrennen darf man Papier nur im Hof. Die Regeln sind klar: Lärm ist untersagt, und die Polizei schließt die Straße ab, wenn Gefahr besteht.'],
    ['Alt werden in der Stadt', 'Meine Großmutter ist Seniorin und lebt seit einem Jahr im Altersheim, weil die Treppe im alten Haus zu steil war. Die Pension reicht für das Heim, obwohl sie nicht viel ist; pensioniert wurde sie mit sechzig. Andere Pensionisten wohnen weiter zu Hause, und der Abwart hilft ihnen beim Einkauf. Der Hausmeister im neuen Haus ist ihr Neffe. Mit achtzig ist man von Hilfe abhängig, aber nicht ohne eigenen Willen: Sie entspannt beim Lesen, faulenzt am Sonntag und amüsiert sich über die Enkel. Nachdenken über die Änderung des Lebens half ihr mehr als jeder Ratschlag. Andrerseits fehlt die alte Nachbarschaft. Die Mobilität ist begrenzt, doch die Betreuung ist gut.'],
    ['Am Samstag', 'Am Samstag machen wir die Wohnung sauber: Ich wasche ab, mache die Fenster ab und putze den Boden. Der Stecker ist kaputtgegangen, deshalb lade ich das Handy im Büro auf und löse das Problem später. Vorher hebe ich die Sachen auf, die durcheinander liegen, und mache das Bett. Beim Kochen fällt mir eine Idee ein, und ich füge ein Gewürz hinzu. Wenn ich die Treppe nach oben gehe, gucke ich auf die Stufe; die Fortsetzung folgt oben. Es ist erforderlich, die Rechnung festzuhalten, denn die Frist steht fest. Genauso verstecke ich die Geschenke, damit die Kinder sie nicht herausfinden. Zwingen kann ich niemanden, aber ich zweifle nicht daran, dass es gelingen wird. Zumindest ein Teil wird rechtzeitig fertig.'],
    ['Aufräumen am Samstag', 'Am Samstag räumen wir die ganze Wohnung auf. Zuerst leere ich den Abfalleimer in der Küche; alles, was wir nicht mehr brauchen, entsorgen wir am Abend. Jeder alte Gegenstand kommt in eine Schachtel. Die blaue Schüssel hat ein Loch, und zwei Teller brechen beim Tragen. Manche Dinge können schnell kaputtgehen, wenn man sie falsch nimmt. Ein Streichholz liegt neben der Kerze, ein Strumpf steckt unter dem Sofa, und die Fernbedienung ist schon wieder weg. Im Kuvert steckt ein Brief von der Versicherung, das Abonnement der Zeitung läuft noch drei Monate. Die Broschüre mit der Bedienungsanleitung lege ich in den Kasten. Meine Tasche war weg, ich habe sie im Fundbüro gefunden. Am Ende bin ich so müde, dass ich nur noch den Mantel anhaben und schlafen will. Was soll ich morgen anhaben? Das frage ich mich jeden Sonntag.'],
    ["Am Geldautomaten", "Am Freitag will ich Geld abheben. Meine Bancomatkarte steckt im Automaten, der Geldautomat am Bahnhof ist der nächste. Ich will dreihundert Franken einzahlen, denn die Miete kommt nächste Woche. Die Bank zahlt dafür nur einen minimalen Zins, das ist nämlich normal. Der Zuschlag für die schnelle Überweisung ist doppelt so hoch wie früher. Für die Miete genügen zweitausend Franken nicht mehr, ebenso steigen die Nebenkosten. Insgesamt zahle ich jetzt zusätzlich hundert Franken, inklusive Heizung und Wasser. Nicht sämtliche Rechnungen sind schon bezahlt, aber die wichtigsten. Der Service war ausgezeichnet, findet meine Nachbarin. Sie sagt, die Beratung sei prima gewesen. «Wie war es?» — «Allerbest!» Für mich ist das die beste Lösung: Ich zahle bargeldlos und behalte den Überblick."],
    ["Die neue Stelle", "Die Firma will im Herbst zehn Leute einstellen. Wer eintreten will, unterschreibt zuerst einen Vertrag; die Personalie liegt beim Betriebsrat, und die Betriebsrätin prüft sie. Die Arbeiterin aus der Werkstatt und die Mitarbeiterin aus dem Büro setzen sich zusammen und wollen morgen über den Plan abstimmen. Der Chef will neue Maschinen einführen und für den Export mehr Leute anstellen; der Fachmann von der Technik fordert sogar einen zweiten Meister, den er als Leiter einsetzen will. Bei der Eröffnung der neuen Halle muss er jeden Morgen eine Tablette einnehmen, sagt er. Die Leiterin will alle auffordern, leise zu sein, und sie setzt sich für längere Pausen ein. Am folgenden Montag beginnt die Schulung. Den Termin für das große Gespräch will der Betrieb noch festsetzen. Wer dabei sein will, soll sich in die Liste einführen? Nein: Wer dabei sein will, soll sich in die Liste eintragen und den Vertrag mitbringen."],
    ["Beschwerde im Geschäft", "Im Geschäft will ich feststellen, dass der Karton leer ist. Es soll feststehen, dass die Lieferung falsch war. Ich will den Kassenzettel festhalten und zeige ihn der Verkäuferin. Eine Reklamation kann viel Geduld erfordern; man darf nicht schreien, sondern soll ruhig sprechen. Ich unterlasse jede laute Beschwerde und warte. Sie will das Etikett entfernen und den Preis neu schreiben. Für den Umtausch eignet sich nur die Rechnung. Ich gebrauche sie also und verwende sie zweimal, weil ich zwei Sachen abmachen muss. Was nützt ein Rabatt, wenn die Ware fehlt? Ich will nicht an der Werbung zweifeln. Ich versäume die Frist nicht, sondern komme am nächsten Tag wieder. Wenn ich aufgeben würde, wäre das Geld weg. Mit dem Chef will ich das direkt abmachen, dann können wir auseinander gehen, ohne Streit. Mit dieser Firma muss man vorsichtig umgehen. Vorläufig warte ich hier und trinke einen Kaffee."],
    ["Lernen mit Methode", "Die Lernerin sitzt jeden Abend zwei Stunden über ihren Heften. Sie will keinen Satz abschreiben, der sie nicht weiterbringt. Dabei bemerkt sie, dass sie zu viele Wörter nachschlagen muss. Jeder Schritt ist klein: erst lesen, dann hören, am Ende schreiben. Die Herausforderung ist nicht die Grammatik, sondern die Zeit. Sie lernt intensiv, aber nicht jeden Tag gleich. Aus dem Material wählt sie jeweils eine Seite aus; dann sucht sie sich irgendein Thema aus, das sie mag. Allgemein bleibt der Test bis Freitag geheim. Eindeutig ist nur die Regel, die sie sich selbst gibt. Nach drei Wochen fühlt sie sich befreit. Das Ergebnis ist befriedigend, mehr noch: es tut gut. Man kann nicht alles auf einmal auswählen, deshalb lässt sie sich beim Aussuchen Zeit."],
    ["Nach dem Streit", "Er wollte sie nicht beleidigen, aber er sagte etwas Dummes. Sie wollte ihn nicht betrügen; es sah nur so aus. Sie will sich nicht weigern, über das Geld zu sprechen. Wir entschließen uns zu warten, obwohl alle sagen, wir seien verrückt. Der Trainer versucht uns zu überreden, aber wir sind entschlossen und bleiben ruhig. Meine Überzeugung ist einfach: Man muss sich anders verhalten. Der Vorfall zeigt nur ihr Verhalten: Sie schreien nicht. Beim Abschied darf man sich verzeihen, auch wenn eine Träne kommt. Ein Kuss sagt mehr als tausend Wörter; sie küssen sich und lachen. Zu diesem Thema kann mir nichts Neues einfallen, und einen besseren Einfall hat niemand."],
    ["Die Nachbarin verschwindet", "Im Haus erzählen alle, jemand wolle Geld stehlen. Zuerst sucht man den Verbrecher nebenan; die Polizei hält sogar die Verbrecherin im Haus für die Täterin, denn die Einbrecherin passt nicht in das Bild. Die Frau will sich gerade scheiden lassen, und nach der Scheidung will sie das Haus verkaufen; die Trennung von ihrem Mann war schon lange klar. Die Polizei macht jetzt öffentlich, was passiert ist; eine Uniform steht vor der Tür. Ein Sozialarbeiter und eine Sozialarbeiterin kommen jeden Tag und suchen nach einer Vermittlung. Alle Anwohner vermissen die Nachbarin; sie wollen sich an eine Gruppe anschließen. Niemand will sie ausschließen. Einen Antrag auf Asyl kann sie hier nicht stellen, aber ein Zimmer findet sich."],
    ["Im Badezimmer", "Am Morgen steht sie vor dem Spiegel. Über der Brust sieht sie einen kleinen Fleck; auf der Lippe ist eine Wunde. Ihr Freund will sich rasieren, sie will sich schminken. Die Frisur sitzt noch nicht, obwohl der Coiffeur gestern zwei Stunden gearbeitet hat. Die Coiffeuse im Dorf hat einen neuen Stil. In der Drogerie kauft sie Creme und ein Vitamin; eine Droge braucht sie nicht. Wenn kleine Tiere beißen, tut das weh; ein Insekt kann auch stechen. Über den Tod denkt man nicht gern nach. Im Sommer will er tauchen lernen, und am Abend stürzen die Preise im Sonderangebot, so ist das Leben. Äußerlich ist alles in Ordnung, und kräftig genug ist sie auch."],
    ["Am Flughafen", "Ein Passagier fragt am Schalter, und eine Passagierin mit zwei Koffern hört zu. Der Steward begrüßt alle, die Stewardess zeigt den Weg. Die Kabine ist klein, aber elegant. Wir müssen uns anschnallen, bevor das Flugzeug startet. Die Klimaanlage ist zu kalt, und der Motor ist elektrisch. Die Distanz zwischen den Sitzen ist klein; zwei Reihen liegen parallel. Ungefähr zwanzig Minuten später beginnt der Flug. Voraussichtlich landen wir um acht, zukünftig fliegen wir direkt. Niemand will sich lange aufhalten. Wir wollen den Weg fortsetzen und sehen einander hinterher."],
    ['Die neue Nachbarin', 'Ein Bub spielt vor dem Haus; die Einwohnerin grüßt ihn. Eine Bewohnerin erzählt, ein Migrant und eine Migrantin seien eingezogen. Worum geht es? Nun, weder der Vermieter noch die Nachbarn wissen es. Meinetwegen kann alles so bleiben; nebenbei bemerkt ist das Haus sehr ruhig. Soviel ich weiß, ist der Typ merkwürdig. Eben! Das Haus in der Mitte und das Haus hinten bleiben leer, und niemand hat jemals dort gewohnt.'],
    ["Einkaufen und kochen", "Jeden Mittwoch kaufe ich eine Karotte, Schlagsahne und ein Stück Fleisch. Für das Faschierte brauche ich nur eine Zutat: Salz. Ich will das Essen zubereiten, und danach muss ich abwaschen. Der Hund will fressen, die Katze will ich füttern. Nach dem Salz bin ich durstig. Die Werbung will uns mehr konsumieren lassen. Jedes Nahrungsmittel soll biologisch sein. Die Etiketten sind farbig; in Österreich sagt man färbig. Das Abgas von den Autos schadet allen, und die Scheibe am Fenster ist schmutzig."],
    ["Beim Sportfest", "Die Kinder wollen mit dem Ball schießen; ein Mädchen trägt eine Puppe. Die Siegerin bekommt einen Preis. Ein Profisportler und eine Zuschauerin sprechen darüber. Der Spezialist und die Spezialistin messen die Zeit. Wenn es hageln will, bleiben alle drinnen. Man spürt den Wind, und die Bäume schütteln sich. Jemand klopft an die Tür; ein Kind will auf den Baum klettern. Die Kleinen rennen über den Platz und schieben den Karren. Ich will den Stein umdrehen; der Gegner wartet schon."],
    ['Wege in der Stadt', 'Die Fußgängerin und die Radfahrerin streiten am Rand des Weges. «Komm hierher!», ruft jemand. Der Weg geht nach oben: rauf bis zum Schloss, dann abwärts zum Fluss. Ein Kind will den Ball runterwerfen. Diese Tür kann nicht zugehen; solche Fehler können oft vorkommen. Ich will die kleine Gasse entdecken und den Zettel aufheben. Sie muss ihr Handy aufladen und die Aufgabe auflösen. In die Liste darf man einen Namen einfügen. Das soll allen auffallen: Die Klasse will ein Stück aufführen.'],
    ["Alt und jung", "Meine Großmutter wohnt im Altenheim. Ein Pensionist und eine Pensionistin treffen sich dort. Ein Senior erzählt von früher. Nichtraucher und Nichtraucherin sitzen getrennt; die Raucherin raucht draußen. Alle Menschen sind gleichberechtigt, und jeder Fehler ist menschlich. Zeit ist wertvoll, Geld allein ist wertlos. Der Ruhm dieser Entdeckung ist weltenweit bekannt. Über Gott und das Geschlecht diskutieren sie lange. Eine Wissenschaftlerin forscht dazu, und die Fragen sind zahlreich."],
    ['Kunst und Presse', 'Die Malerin und die Schriftstellerin stellen zusammen aus. Der Auftritt beginnt um acht; eine Gruppe will zuerst auftreten und danach vorlesen. Die Neuigkeit steht im Forum der Zeitung. Die Gratulation kommt von der Architektin, und die Vertreterin der Stadt will mehr Geld versprechen. Die Bilder stammen aus dem Süden. Der Wind kann es extrem treiben. «Allerschönst!», sagt der Kritiker. Besondere Wünsche erfüllt das Haus gern, und daraus entsteht ein besonderer Abend.'],
    ["Auf dem Amt", "Auf dem Amt sind heute zwei Personen abwesend. Man soll den Besuch vorher ankündigen. Die Abwartin schließt die Tür um vier. Die Firma will einen Mitarbeiter entlassen. Eltern wollen Kinder erziehen; die Erziehung ist Aufgabe aller. Die Stadt will Neuzuzüger integrieren. Die gesamte Verwaltung arbeitet langsam, und die Antwort ist meistens negativ. Ausschließlich am Montag gibt es einen Rabatt. Das soll nicht von mir abhangen. Die Familie will den Garten vergrößern, obwohl der Käse im Kühlschrank stark stinken kann. Die Absenderin steht oben auf dem Brief. Auf der Vorder- und Rückseite steht eine Nummer. Sie muss allein zurechtkommen."],
  ].map((r, i) => text('b1-r' + (i + 1), 'B1', r[0], r[1]));
  const articles = [
    ["العمل عن بعد", "Einerseits spart die Arbeit zu Hause den Weg und gibt dem Tag eine Stunde zurück. Andererseits fehlt die Grenze zwischen Tag und Abend, und wer keine Grenze zieht, arbeitet am Ende länger als im Büro. Die Erfahrung aus vielen Teams zeigt: Die Maßnahme hilft nur, wenn das Team die Zeiten nennt. Ein fester Anfang, ein festes Ende, eine Pause, die niemand verschiebt — das klingt klein, ist aber der ganze Unterschied. Fehlt diese Regel, wird aus Freiheit Kontrolle: Der Chef ruft abends an, die Kollegen schreiben am Sonntag, und niemand weiß, wann der Feierabend beginnt. Die Technik ist dabei nicht die Frage; sie funktioniert längst. Ich halte deshalb nicht das Büro für das Problem und nicht das Wohnzimmer für die Lösung, sondern die gemeinsame Regel. Wer sie einmal aufschreibt und beide Seiten daran hält, kann von zu Hause arbeiten, ohne dass die Arbeit das Haus besetzt."],
    ["الإيجار", "Die Miete steigt. Das ist die Zahl, und sie steht in jedem Vertrag, in jeder Statistik und in jeder Zeitung. Was die Quelle nicht nennt, ist die Ursache. Wer in den Bericht schaut, findet keine Schuldigen, sondern einen Vergleich mit dem Vorjahr, und dieser Vergleich zeigt den Anstieg, nicht den Grund. Das ist keine Schwäche des Berichts, sondern seine Grenze: Zahlen beschreiben, was passiert ist, und nicht, warum es passiert ist. Wer trotzdem einen Schuldigen braucht, sucht ihn am Ende in den Wohnungen der anderen und findet dort Menschen, die dieselbe Rechnung bezahlen. Ich lese solche Meldungen deshalb zweimal: einmal für die Zahl und einmal für das, was fehlt. Wer die Zahl nennt und die Deutung offen lässt, hilft mehr als der, der beides in einen einzigen Satz presst und damit die halbe Wahrheit laut macht."],
    ["الهجرة اليومية", "Viele fahren jeden Tag in die Stadt, und die Zahl dieser Fahrten wächst. Der Vorteil ist die Arbeit: Sie ist dort, wo die Aufträge sind, und nicht dort, wo die Mieten niedrig sind. Der Nachteil ist die Zeit. Wer morgens um fünf aufsteht, um um neun anzufangen, bezahlt die Fahrt mit Zeit, die ihm dann fehlt, und diese Rechnung steht in keiner Statistik. Zwar gibt es den frühen Zug, aber nicht überall: Die Grenze ist der Ort ohne frühen Zug, also der Ort, an dem ein Umzug nicht hilft, sondern nur ein anderes Leben. Deshalb reicht es nicht, den Ausbau der Straßen zu fordern. Wer diese Menschen ernst nimmt, plant nicht nur die Strecke, sondern auch den Tag: Arbeitszeiten, Kinderbetreuung, Homeoffice. Sonst gewinnt die Stadt die Menschen, die jeden Morgen kommen, und verliert ihre Tage."],
    ["المدرسة والرقمنة", "Ein Gerät ersetzt keine Lehrkraft. Es kann Übung geben, es kann wiederholen, es kann prüfen, aber es kann keine Rückfrage beantworten, die noch nicht im Programm steht. Genau diese Rückfrage aber entscheidet, ob ein Kind versteht oder nur wiederholt. Wer Tablets will, spricht von Chancen und nennt selten die Kosten. Wer zahlt, gehört zur Frage: die Stadt, die Eltern, die Stiftung, der Hersteller mit seinem Rabatt? Nicht jede Schule hat dasselbe Budget, und keine Schule sollte über ihr Budget streiten müssen, während die Kinder warten. Ich bin nicht gegen Technik im Unterricht. Ich bin dagegen, sie als Ersatz zu verkaufen und die Lehrkraft dabei nur als Kosten zu behandeln. Ein Gerät ist ein Werkzeug; die Frage, wie man es benutzt, bleibt eine Frage des Unterrichts und keine der Technik."],
    ["الصحة والوقاية", "Die Praxis ist voll, die Termine sind knapp, und wer erst reagiert, wenn es weh tut, wartet am längsten. Ein früher Termin hilft nur, wenn die Versicherung klar ist. Vorher muss man wissen: Zahlt sie die Vorsorge, zahlt sie die Nachsorge, und welche Untersuchung braucht eine Überweisung? Ohne diese Antworten wird die Vorsorge zu einer Rechnung, die man nicht geplant hat. Die Absicht, gesund zu bleiben, reicht nicht als Plan; sie ist ein Gefühl und keine Maßnahme. Ein Plan hat einen Termin, einen Betrag und eine Person, die zuständig ist. Deshalb schreibe ich jedes Jahr im Januar drei Zeilen auf: was ich prüfen lasse, was es kostet, wer es übernimmt. Das ist nicht groß, aber es ist der Unterschied zwischen einem Plan und einer Untersuchung, die wirklich stattfindet."],
    ["الاستهلاك", "Nicht nur der Preis zählt. Ein billiges Gerät, das schnell kaputt ist, kostet später mehr: die Reparatur, der Ersatz, die Zeit und nicht zuletzt der Ärger. Der Beleg zeigt den Kauf, nicht die Qualität; er beweist, dass man bezahlt hat, und nichts darüber, wie lange das Stück hält. Wer eine teure Maschine für den Haushalt kauft, kann deshalb nicht nur zwei Angebote vergleichen und dann das günstigere nehmen. Er sollte nach dem Verbrauch fragen, nach der Garantie und nach dem Preis der Teile, die man ersetzen muss. Allerdings ist dieser Vergleich Arbeit, und diese Arbeit wird selten bezahlt. Ich verstehe jeden, der müde wird und einfach das mittlere Angebot nimmt. Aber ich widerspreche dem Satz, dass man beim billigen Kauf gewinnt. Gewonnen hat der Verkäufer, und verloren hat der Käufer, der in zwei Jahren wieder vor dem Regal steht."],
    ["النقل", "Der Bus ist langsam, der Zug ist voll, und beide fahren zu den Zeiten, die für die Menschen im Bus und im Zug nicht passen. Eine Maßnahme ohne Alternative scheitert am ersten Ausfall: Wenn die Linie gestrichen wird, steht der Mensch auf der Straße, und die Diskussion über den Klimaschutz führt er dann nicht mehr. Der Plan braucht einen zweiten Weg. Das kann eine andere Linie sein, ein Weg für die Fahrräder, ein Platz für die Autos am Bahnhof oder ein Recht auf Homeoffice an zwei Tagen in der Woche. Zwar kostet jeder dieser Wege Geld, aber weniger als ein System, dem die Leute nach der ersten Störung nicht mehr vertrauen. Ich habe nichts gegen Verbote, wenn sie den Ersatz gleich mitbringen. Ein Verbot ohne Ersatz ist nur ein Satz, und Sätze fahren keine Menschen nach Hause."],
    ["الطاقة", "Energie sparen ist eine Gewohnheit, keine große Tat. Die Folge ist klein, aber sichtbar: die Rechnung am Ende des Jahres, die Temperatur im Zimmer, das Licht, das niemand braucht. Wer alles auf einmal will, bleibt beim Alten, weil der erste Schritt zu groß war und der zweite deshalb nie kam. Ich habe das selbst erlebt: Nach dem Umzug wollten wir dreißig Dinge ändern, und nach zwei Wochen war nichts davon geblieben. Später haben wir mit einer einzigen Regel angefangen, die Heizung im Schlafzimmer eine Stufe niedriger. Ein Jahr danach war die Regel keine Regel mehr, sondern eine Gewohnheit, und der Verbrauch war um zwanzig Prozent gesunken. Das ist keine Geschichte von Verzicht, sondern eine von Reihenfolge. Wer die Reihenfolge kennt, kann am Ende auch die großen Entscheidungen treffen, über den Schutz des Hauses, das Auto und die Heizung, ohne dass ihm vorher die Kraft ausgeht."],
    ["العنوان", "Die Überschrift verspricht mehr, als der Text hält. Wer nur den Titel liest, glaubt an ein Ergebnis, das die Untersuchung nicht gefunden hat; in der Studie steht dann ein Zusammenhang, in der Schlagzeile ein Beweis. Viele Leser machen die Aussage nicht wahr, weil sie die Quelle gar nicht öffnen. Hinzu kommt ein zweites Problem: Die Plattform ist nicht die Quelle. Wer in einer Gruppe oder unter einem kurzen Video liest, liest eine Zusammenfassung von einer Zusammenfassung, und jede Stufe verliert etwas. Ich prüfe deshalb seit einem Jahr nur zwei Dinge: Wer hat gemessen? Und wie viele Fälle waren es? Fehlt eine der beiden Antworten, klicke ich weiter und behalte den Satz nicht im Kopf. Das ist streng, aber es hilft mir, am Abend über Zahlen zu streiten, die am Morgen noch niemand geprüft hat."],
    ["التطوع", "Ehrenamt trägt den Verein, solange die Zeit da ist. Die Kasse ist nur die halbe Wahrheit; die andere Hälfte sind die Abende, an denen jemand die Halle putzt, das Turnier zählt und die Kinder nach Hause bringt. Aus eigener Erfahrung bricht es nicht, weil die Leute nur an sich denken, sondern dann, wenn alle gleichzeitig arbeiten. Die Prüfungen liegen im selben Monat, die Feste im selben Wochenende, und plötzlich steht dieselbe kleine Gruppe überall. Das ist eine Grenze, kein Vorwurf. Wer diese Grenze sieht, verteilt die Aufgaben nicht nach dem Willen der Mitglieder, sondern nach dem Kalender. Außerdem hilft es, die Leitung alle zwei Jahre zu wechseln, damit Wissen nicht in einer Person hängt. Ich sage das ohne Moral. Ein Verein, der sich über den Zeitplan der Mitglieder Gedanken macht, gewinnt mehr Helfer als einer, der jedes Jahr um dieselben drei bittet."],
      ["السياحة", "Die Stadt lebt vom Besuch und leidet unter ihm. Beide Seiten gehören in den Satz, und wer eine davon nicht nennt, redet nicht über die Stadt, sondern über seine Meinung. Zwar bringt der Tourismus Geld in die Läden und in die Hotels, aber er treibt auch die Mieten und füllt die Straßen, in denen die Leute wohnen, die keine Ferien haben. Ich halte deshalb nichts von der Frage, ob der Tourismus gut oder schlecht ist; sie ist zu groß und führt zu keinem Beschluss. Besser ist eine Reihe kleiner Fragen: Wie viele Betten, wie viele Wohnungen, wie viele Busse, und wer räumt am Morgen den Müll weg? Das Urteil kommt danach, nicht vorher. Eine Stadt, die diese Zahlen kennt, kann steuern. Eine Stadt, die nur gut findet oder nur klagt, verliert beides: die Gäste und die Bewohner."],
    ["اللغة في العمل", "Ein Zertifikat öffnet die Tür nicht allein. Es beweist, dass jemand eine Prüfung bestanden hat, und nichts darüber, ob er am Montag früh den Ablauf erklären kann, wenn zwei Kollegen krank sind und der Kunde wartet. Die Frage ist deshalb nicht, welches Niveau im Lebenslauf steht, sondern ob die Person den Ablauf erklären kann: was zuerst, was danach, was, wenn es schiefgeht. Ein Beispiel aus dem Tag sagt mehr als eine Note. Ich habe in Gesprächen um eine Stelle beides erlebt: Bewerber mit einem hohen Zertifikat, die auf die Frage nach einem Fehler schwiegen, und Bewerber ohne Zertifikat, die in drei Sätzen erzählten, wie sie eine Lieferung gerettet hatten. Die zweite Gruppe bekam die Stelle. Das heißt nicht, dass Prüfungen ohne Wert sind. Es heißt, dass die Sprache im Betrieb eine andere Prüfung ist, und diese Prüfung findet jeden Tag statt."],
    ["الهدر", "Weniger wegwerfen ist konkret. Der Satz «die Umwelt ist wichtig» reicht nicht, weil er nichts ändert: Niemand weiß danach, was er am Montag anders machen soll. Ich habe angefangen, den Müll einer Woche zu zählen, und das Ergebnis war unangenehm: Plastik aus der Küche, Brot, das zu lange lag, drei Sachen aus dem Kühlschrank, die niemand mehr essen wollte. Seitdem kaufe ich zweimal in der Woche und nicht einmal für sieben Tage, und ich schreibe auf, was übrig geblieben ist. Die Folge muss in den Mülltonnen sichtbar sein, nicht nur im Satz. Wer nur redet, kann jedes Jahr dasselbe sagen und jedes Jahr dasselbe wegwerfen. Wer zählt, verändert den Einkauf. Das ist keine große Politik, aber es ist eine Maßnahme, die man an einem Montag beginnen kann, ohne auf ein Gesetz zu warten."],
    ["الرياضة والمال", "Der Verein braucht Beitrag und Zeit, und beides ist knapp. Kostenlos für alle ist selten wahr: Jemand zahlt die Halle, die Trainerin, die Kleidung und den Strom, und wenn es nicht die Mitglieder sind, dann die Stadt oder eine Firma mit eigenen Interessen. Wer profitiert, und wer zahlt, sind zwei Fragen, und ein Verein, der nur die erste stellt, verliert am Ende die, die zahlen. Allerdings darf der Beitrag nicht zu groß werden. Deshalb gibt es Ermäßigungen, kleinere Preise für Familien und die Regel, dass niemand wegen des Geldes aufhört; Vereine, die das haben, sind voller und ruhiger. Ich zahle meinen Beitrag gern, wenn ich weiß, wohin er geht. Ein Verein, der einmal im Jahr zeigt, was die Halle kostet, muss nicht um Verständnis bitten. Er hat es dann schon."],
    ["الدعم الثقافي", "Ein Antrag auf Geld hilft, wenn die Frist klar ist. Viele Anträge scheitern nicht am Inhalt, sondern an einem Datum, das niemand gelesen hat, oder an einem Beleg, der im Ordner fehlte. Ohne Beleg bleibt der Antrag schwach: Wer eine Summe nennt, muss zeigen, wo sie gebraucht wird, und wer sie ausgibt. Der Ton der Begründung bleibt sachlich; ein großes Wort über die Bedeutung der Kultur überzeugt niemanden in der Verwaltung, eine Tabelle schon. Ich habe zwei Jahre in einem kleinen Theater gearbeitet, und wir haben jedes Mal dieselben Fehler gemacht, bis eine Kollegin einen Kalender an die Wand hängte und drei Termine rot markierte. Danach kam das Geld pünktlich. Das ist keine Geschichte über Bürokratie, sondern über Reihenfolge: erst die Liste, dann der Brief, dann die Frist. Wer so arbeitet, muss weniger bitten und kann mehr planen."],
    ["الجيران", "Lärm ist eine Tatsache, wenn er gemessen wird. Alles andere ist eine Wertung: Der Satz, dass der Nachbar keine Rücksicht nimmt, braucht mehr als ein Gefühl, nämlich eine Uhrzeit, eine Dauer und eine Wiederholung. Ich habe das in meinem alten Haus gelernt. Drei Jahre lang beschwerte ich mich über die Musik von oben, und niemand glaubte mir, weil ich nur sagte, es sei sehr laut. Dann schrieb ich zwei Wochen lang auf, wann es begann und wann es endete, und plötzlich war es ein Gespräch und kein Streit. Eine Bitte kommt vor dem Vorwurf. Wer zuerst fragt, bekommt häufiger eine Antwort als der, der zuerst streitet. Und wenn die Bitte nichts hilft, ist die Liste immer noch da, und mit ihr geht man weiter, ohne die Stimme zu erheben."],
    ["الشاشة", "Die Zeit an der Fläche steigt. Das zeigt die Zahl, und diese Zahl ist der einzige Teil der Meldung, der gemessen wurde. Ob das schadet, ist eine Deutung. Wer morgens eine halbe Stunde liest und abends einen Film sieht, hat dieselbe Zahl auf dem Papier wie jemand, der die halbe Nacht spielt, und doch ist es nicht dasselbe Leben. Die Quelle nennt keine Ursache für jede Stunde, und sie kann es nicht: Sie hat gefragt, wie lange jemand etwas benutzt, und nicht, wie es ihm danach ging. Ich nehme solche Zahlen ernst und lese sie langsam. Sie sagen mir, wo ich genauer lesen sollte, nicht, was ich dort finde. Wer die Zahl zur Diagnose macht, lässt den zweiten Schritt aus; und der zweite Schritt, der Blick in den eigenen Tag, ist der, der etwas verändert."],
    ["التقاعد", "Früher aufhören klingt gut und kostet Beitrag. Die Grenze ist das Einkommen, nicht der Wunsch; wer mit 63 aufhören will, braucht entweder mehr Jahre mit Einzahlung oder weniger Ausgaben, und diese Rechnung bleibt. Ein Vergleich ohne Zahl bleibt ein Wunsch: Man hört von Kollegen, die es geschafft haben, und vergisst, dass sie eine andere Stelle, ein anderes Haus und ein anderes Konto hatten. Ich habe einen Rechner benutzt, und das Ergebnis war schlicht: Mit dem Plan, den ich heute habe, ist ein frühes Aufhören möglich, aber knapp, und jede größere Ausgabe verschiebt ihn um Monate. Das ist unangenehm und nützlich zugleich. Seitdem weiß ich, was die Entscheidung kostet, und ich kann sie treffen, statt sie nur zu denken."],
    ["القرية والمدينة", "Im Vergleich zur Stadt ist die Miete niedrig, und im Vergleich zur Stadt ist der Weg zum Arzt weit. Nicht alles ist gleich: Wer im Dorf wohnt, spart beim Wohnen und zahlt beim Verkehr; wer in der Stadt wohnt, spart den Weg und zahlt die Miete. Wer umziehen will, sollte deshalb nicht eine Liste machen, sondern zwei, und beide ehrlich. Die Grenze ist der Notfall, nicht der Einkauf. Solange alles ruhig läuft, ist das Dorf günstiger und schöner. Wenn um zwei Uhr nachts jemand ins Krankenhaus muss, entscheidet nicht der Preis der Wohnung, sondern die Minuten bis zur Tür. Ich kenne Familien, die wegen dieser Minuten zurück in die Stadt gezogen sind, und andere, die im Dorf geblieben sind und sich organisiert haben: ein Auto, ein Nachbar mit Zeit, ein Nachbar, der nachts das Telefon nimmt. Beide Lösungen sind vernünftig, wenn man sie vorher wählt."],
    ["العدل في الامتحان", "Ein Modul rettet das andere nicht. Das ist hart und klar, und es ist die Regel, die viele Prüfungen von der Schule unterscheidet: Wer in einem Teil schwach bleibt, besteht nicht durch einen starken anderen. Man kann über diese Regel streiten, und ich kenne die Einwände: Ein schlechter Tag, ein schwieriger Text, ein Thema, das man nicht mochte. Aber die Regel hat ein Ziel, das ich für richtig halte: Wer eine Sprache im Alltag, im Büro und im Kurs benutzt, muss in allen vier Bereichen bestehen, nicht nur in der Hälfte, die ihm liegt. Wer einen Teil schwach lässt, verschwindet nicht durch einen starken anderen; er verschwindet nur aus der Rechnung, und das ist etwas anderes. Deshalb plane ich seit Monaten jede Woche mindestens einen Tag für die schwächste Fertigkeit ein, und ich hasse diesen Tag. Aber ich bestehe ihn."],
].map((r, i) => text('b2-a' + (i + 1), 'B2', r[0], r[1]));
  const novel = {
    id: 'novelle-zimmer',
    title: 'Das Zimmer in Sousse',
    note: 'نوفيلة أصلية مكتملة، ليست رواية منشورة. الملك العام لم يُنسخ.',
    chapters: [
      ["الوصول", "Der Zug hatte zwei Stunden Verspätung, als Sara an einem Dienstag im Oktober am Abend in Sousse ankam. Auf dem Bahnsteig war es nass vom Regen, und die Lampen über den Gleisen flackerten. Sie zog den Koffer hinter sich her, suchte die Straße auf dem Zettel und fand sie erst nach zwanzig Minuten. Das Haus lag am Rand der alten Stadt, die Tür war offen, und im ersten Stock war kein Licht. Die Nachricht hatte versprochen, der Schlüssel liege unter dem Stein. Sara ging in die Knie, hob den Stein hoch und suchte mit der Hand über den Boden vor der Tür. Da war nichts, nur Staub und ein trockenes Blatt. Sie setzte sich auf den Koffer und las den Zettel noch einmal, Wort für Wort. Die Wohnung war im Erdgeschoss, das stand eindeutig da. Sie ging um das Haus, klopfte an einer zweiten Tür, wartete, klopfte noch einmal. Im Flur war Licht; sie sah es durch das schmale Fenster über der Tür. Jemand war also da, oder jemand war gegangen und hatte vergessen, das Licht zu löschen. Sie rief, erst leise, dann lauter. Niemand öffnete. Später kam ein Nachbar mit einem Hund vorbei und fragte, ob sie Hilfe brauche. Sie sagte, sie habe den Schlüssel nicht, und zeigte ihm den Zettel. Der Mann las die Nachricht, sagte nichts und meinte, der Vermieter sei schon seit Wochen nicht mehr im Haus gewesen. Er bot ihr an, im Café an der Ecke zu warten; Sara aber wollte die Sache klären. Sie schrieb eine Nachricht an die Nummer auf dem Zettel, schickte sie ab und blieb vor der Tür sitzen, bis es dunkel wurde. Um zehn Uhr stand sie auf, nahm den Koffer und ging in das Café. Sie bestellte Tee und ein Stück Brot und schrieb in ihr Heft: Ankunft, Tür, Schlüssel, morgen."],
      ["الجارة", "Am nächsten Morgen stand Sara um sieben vor dem Haus und klopfte noch einmal, diesmal laut und ohne Pause. Nach einer Minute öffnete eine Frau, die eine Jacke trug und nicht müde war, sondern ärgerlich. Sie hieß Leila und wohnte direkt über Sara. Sie fragte, ob Sara die Neue aus dem Erdgeschoss sei, und Sara sagte ja. Da ging Leila die Treppe nach oben und kam mit einem Schlüssel wieder. Der Schlüssel habe bei ihr gelegen, erklärte sie, weil der Vermieter die Stadt verlassen hatte und niemand mehr im Haus war, der sich um solche Dinge kümmerte. Sie sagte das ohne großes Wort, so wie man sagt, dass es regnet. Sara bedankte sich und fragte gleich nach dem Wasser, denn im Bad lief nichts. Leila bewegte die Schultern: Das Wasser komme erst am Abend, das sei hier so, und wer am Morgen duschen wolle, müsse es heiß machen und in einem Eimer stehen lassen. Sara öffnete die Wohnung. In der Luft war Staub, und alles war aus altem Holz. Die Fenster gingen auf den Hof, die Küche war klein, aber sauber, und in der Ecke stand ein Tisch mit zwei Stühlen. Sie packte den Koffer aus, hängte die Kleidung in den Schrank und legte die Papiere auf den Tisch. In dem Kasten fand sie einen alten Kalender aus dem Jahr vorher; jemand hatte auf die Rückseite vier Wörter geschrieben, die Sara nicht lesen konnte. Am Abend kam das Wasser tatsächlich, erst braun, dann klar. Sara wusch sich, kochte Tee und setzte sich ans Fenster. Über ihr hörte sie Schritte, dann Musik, dann nichts. Sie schrieb in ihr Heft: Leila, Wasser abends, Vermieter weg, Kalender."],
      ["العمل", "Der Kurs begann um acht, und Sara war am ersten Tag schon um halb acht da, weil sie den Weg noch nicht kannte. Der Raum der Klasse lag im zweiten Stock einer Schule, die in den Ferien halb leer war. Vierzehn Leute saßen an den Tischen, die meisten so müde wie sie, und die Lehrerin schrieb das Thema an die Tafel: Bewerbung und Alltag. Nach dem Kurs arbeitete Sara halbtags in einem kleinen Büro am Hafen. Sie schrieb Rechnungen in den Computer, ordnete Briefe und lernte dabei Wörter, die im Kurs nie waren. Der Chef sprach schnell und sprach die Endungen nicht aus, aber er war geduldig, wenn sie nachfragte. Am dritten Tag sagte er, sie solle die Telefone annehmen; sie sagte, das könne sie noch nicht, und er lachte und meinte, dann lerne sie es eben. Das Geld reichte für die Miete und für das Essen, mehr nicht. Wenn Sara abends nach Hause kam, war der Markt schon zu, und die kleinen Läden hatten nur Brot und Joghurt. Einerseits war sie froh über die Arbeit, andererseits fehlte ihr die Zeit. Sie rechnete auf einem Blatt Papier: Kurs am Morgen, Büro bis fünf, Markt, Haushalt, Wiederholung. Dann ließ sie zwei Abende aus und schrieb die Grenze in ihr Heft: vier Abende, nicht sieben. In der zweiten Woche fragte Leila sie, ob sie am Wochenende mitkommen wolle, in die Berge. Sara sagte, sie müsse lernen. Leila sah sie an und sagte nur: «Du musst auch atmen.» Sara dachte darüber nach, auf dem ganzen Weg nach Hause."],
      ["الخطأ", "Am Donnerstag kam die Lieferung zu spät. Der Fahrer rief um elf an und sagte, der Wagen stehe noch in Sfax, es könne Abend werden. Sara notierte die Zeit und rief den Chef an, aber der war in einer Sitzung. Um zwölf musste sie das Blatt mit den Terminen zum Amt schicken, und weil die Papiere für die Lieferung fehlten, ging es ohne die Sendung nicht. Sie saß vor dem Telefon und begriff langsam, dass sie den Termin mit dem Amt verloren hatte. Sie schrieb eine kurze Beschwerde. Erstens die Tatsache: Lieferung am Donnerstag nicht angekommen, Termin nicht möglich, Kosten entstanden. Zweitens die Folge: Die Firma kann die Papiere erst am Montag abgeben, die Frist läuft am Dienstag ab. Drittens die Bitte: um eine neue Bestätigung und um eine Uhrzeit am Montag früh. Sie nannte keine Schuld und keine bösen Wörter, sie schrieb nicht «Sie haben» und nicht «immer wieder», sondern nur, was passiert war und was sie brauchte. Am Ende las sie den Brief zweimal und schickte ihn ab. Der Chef rief am Abend zurück und fragte, warum sie nicht einfach gewartet habe. Sara las ihm den zweiten Absatz vor. Er schwieg kurz und sagte dann: «Gut. Weiter so.» Sie legte auf, und ihre Hand bewegte sich ein wenig, ob aus Wut oder aus Erleichterung, wusste sie nicht. Am Freitag lag eine neue Uhrzeit im Briefkasten, Montag, acht Uhr dreißig, mit einer Unterschrift, die sie nicht lesen konnte. Sie steckte den Zettel in die Tasche innen in der Jacke und ging zur Arbeit."],
      ["المطر", "Im Winter regnete es drei Tage ohne Pause. Der Hof stand unter Wasser, und die Löcher für das Wasser, die im Sommer trocken gewesen waren, füllten sich mit Blättern und Müll. Der Hund der Nachbarn wartete vor der Tür und wollte nicht nach draußen; sein Besitzer hob ihn hoch und trug ihn über das Wasser auf dem Boden, und der Hund sah dabei aus wie ein nasses Paket. Sara lernte in diesen Tagen, was ein Dach bedeutet. Im Schlafzimmer kam an einer Stelle Wasser durch, zuerst langsam, dann schneller. Sie stellte einen Eimer unter das Loch, und weil sie keine zweite Schüssel hatte, nahm sie die aus der Küche. Am zweiten Tag kam Leila mit einer Kanne Tee die Treppe herunter und blieb zwei Stunden. Sie sprachen nicht über das Wetter als Gefühl, sondern über den Plan. Wer ruft den Vermieter an, und bis wann? Wer schreibt die Nachricht, wenn niemand antwortet? Leila hatte eine Nummer von einem Mann, der im Sommer auf dem Dach des Hauses nebenan gearbeitet hatte. Sara hatte ein Heft, in dem jede Reparatur stand, mit Datum und Preis. Sie legten beides auf den Tisch, und zum ersten Mal seit Wochen kam Sara die Wohnung nicht wie etwas für kurze Zeit vor, sondern wie eine Aufgabe. Am dritten Abend hörte der Regen auf. Der Hof war im Licht der Lampe hell, und die Nachbarn kamen aus den Häusern, um zu sehen, was übrig war. Sara stand mit Leila an der Tür, und Leila sagte: «Im Frühling ist es hier schön. Warte ab.» Sara sagte nichts, aber sie glaubte es ihr."],
      ["القرار", "Im Mai war das Zimmer hell. Die Sonne kam am Morgen durch das Fenster über dem Tisch, und Sara musste die Papiere zur Seite legen, wenn sie schrieb. Ein Vogel saß auf dem Holz vor dem Fenster und flog erst weg, als sie es öffnete. Die Wohnung war immer noch klein, das Haus immer noch alt, und der Vermieter immer noch weit weg. Aber Sara kannte inzwischen die Stimmen des Hauses: die Schritte über ihr um sieben, die Musik am Freitag, den Hund, der gegen die Tür sprang, wenn Leila nach Hause kam. Sie blieb. Nicht weil alles gut war, sondern weil sie den Ablauf kannte: Kurs am Morgen, Büro bis fünf, Markt am Dienstag, ein Abend frei. Der Plan war nicht schön, aber er passte in die Woche, und die Woche passte zu ihr. Sie hatte in den Monaten vorher gelernt, dass ein Ort nicht besser wird, wenn man ihn wechselt, sondern wenn man seine Grenzen kennt. An einem Samstag räumte sie den Kasten auf, in dem noch der alte Kalender lag. Sie sah die vier Wörter auf der Rückseite zum ersten Mal richtig und las sie laut vor: «Für den, der bleibt.» Dann legte sie den zweiten Schlüssel neben den Kalender, schloss den Kasten und setzte sich ans Fenster. Leila klopfte oben an die Decke, wie sie es jeden Samstag tat. Sara klopfte zweimal zurück. Später schrieb sie ihr einen Satz, den sie nicht erklärte und nicht länger machte, weil er lang genug war: «Ich bleibe bis zum Sommer.» Sie las ihn zweimal, änderte nichts und schickte ihn ab."],
    ].map((c, i) => ({ n: i + 1, title: c[0], body: c[1] }))
  };
  root.DW_LIBRARY = {
    A1: A1,
    A2: A2,
    B1: { texts: B1, magazine: text('b1-mag', 'B1', 'مجلة السكن والعمل', B1.map(t => t.body).join(' ')) },
    B2: { novel: novel, articles: articles }
  };
})(typeof window !== 'undefined' ? window : global);
